insert into questions_v5_seed
  (category, question, options, answer_index, context, difficulty, question_en, options_en, context_en)
values
  ('deportes', '¿Cada cuántos años se celebran los Juegos Olímpicos de verano?', '["Cada 2","Cada 3","Cada 4","Cada 5"]'::jsonb, 2, 'Los JJ.OO. de verano se celebran cada 4 años desde 1896. Los de invierno también, alternándose cada 2 años con los de verano desde 1994.', 'easy', 'How often are the Summer Olympic Games held?', '["Every 2","Every 3","Every 4","Every 5"]'::jsonb, 'The Summer Olympics have been held every 4 years since 1896. The Winter Games too, alternating every 2 years with the Summer Games since 1994.'),
  ('deportes', '¿Qué selección ha ganado más Mundiales de fútbol masculino?', '["Alemania","Italia","Argentina","Brasil"]'::jsonb, 3, 'Brasil ha ganado 5 Copas del Mundo (1958, 1962, 1970, 1994, 2002). Es el único país que ha participado en todas las ediciones.', 'easy', 'Which national team has won the most men''s football World Cups?', '["Germany","Italy","Argentina","Brazil"]'::jsonb, 'Brazil has won 5 World Cups (1958, 1962, 1970, 1994, 2002). It is the only country to have played in every edition.'),
  ('deportes', '¿Cuántos jugadores tiene un equipo de baloncesto en cancha?', '["4","5","6","7"]'::jsonb, 1, 'Cada equipo juega con 5 jugadores. El baloncesto lo inventó James Naismith en 1891 en Springfield, Massachusetts.', 'easy', 'How many players does a basketball team have on the court?', '["4","5","6","7"]'::jsonb, 'Each team plays with 5 players. Basketball was invented by James Naismith in 1891 in Springfield, Massachusetts.'),
  ('deportes', '¿En qué deporte se utiliza un "birdie"?', '["Tenis","Bádminton","Golf","Cricket"]'::jsonb, 2, 'En golf, "birdie" significa un golpe bajo el par del hoyo. "Bogey" es uno por encima del par y "eagle" dos por debajo.', 'medium', 'In which sport is a ''birdie'' used?', '["Tennis","Badminton","Golf","Cricket"]'::jsonb, 'In golf, a ''birdie'' means one stroke under par for the hole. A ''bogey'' is one over par and an ''eagle'' two under.'),
  ('deportes', '¿Cuántos jugadores forman un equipo de fútbol en cancha?', '["10","11","12","9"]'::jsonb, 1, 'Cada equipo de fútbol tiene 11 jugadores, incluyendo al portero. Las reglas modernas se codificaron en Inglaterra en 1863.', 'easy', 'How many players make up a football team on the field?', '["10","11","12","9"]'::jsonb, 'Each football team has 11 players, including the goalkeeper. The modern rules were codified in England in 1863.'),
  ('deportes', '¿En qué país se inventó el tenis moderno?', '["Francia","Estados Unidos","Reino Unido","Australia"]'::jsonb, 2, 'El tenis moderno (lawn tennis) lo inventó Walter Clopton Wingfield en Inglaterra en 1873. Wimbledon, fundado en 1877, es el torneo más antiguo.', 'medium', 'In which country was modern tennis invented?', '["France","United States","United Kingdom","Australia"]'::jsonb, 'Modern tennis (lawn tennis) was invented by Walter Clopton Wingfield in England in 1873. Wimbledon, founded in 1877, is the oldest tournament.'),
  ('deportes', '¿Cuál es la distancia exacta de una maratón?', '["40 km","42,195 km","45 km","50 km"]'::jsonb, 1, 'Una maratón mide 42,195 km. La distancia se fijó en los JJ.OO. de Londres 1908 por el recorrido entre el castillo de Windsor y el estadio.', 'medium', 'What is the exact distance of a marathon?', '["40 km","42.195 km","45 km","50 km"]'::jsonb, 'A marathon is 42.195 km. The distance was set at the 1908 London Olympics based on the route from Windsor Castle to the stadium.'),
  ('deportes', '¿Qué tenista logró el Golden Slam en un mismo año, en 1988?', '["Martina Navratilova","Steffi Graf","Serena Williams","Chris Evert"]'::jsonb, 1, 'Steffi Graf ganó en 1988 los cuatro Grand Slam individuales y el oro olímpico, hazaña conocida como Golden Slam de calendario.', 'medium', 'Which tennis player achieved a calendar-year Golden Slam in 1988?', '["Martina Navratilova","Steffi Graf","Serena Williams","Chris Evert"]'::jsonb, 'In 1988, Steffi Graf won all four singles Grand Slams and Olympic gold, a feat known as the calendar-year Golden Slam.'),
  ('deportes', '¿De qué nacionalidad fue el ciclista Eddy Merckx?', '["Holandés","Belga","Francés","Italiano"]'::jsonb, 1, 'Eddy Merckx es belga, ganador de 5 Tours de Francia, 5 Giros y 1 Vuelta. Es considerado el mejor ciclista de la historia.', 'hard', 'What nationality was the cyclist Eddy Merckx?', '["Dutch","Belgian","French","Italian"]'::jsonb, 'Eddy Merckx is Belgian, winner of 5 Tours de France, 5 Giros and 1 Vuelta. He is considered the greatest cyclist in history.'),
  ('deportes', '¿En qué deporte se disputa la Copa Stanley?', '["Baloncesto","Hockey hielo","Béisbol","Fútbol americano"]'::jsonb, 1, 'La Stanley Cup es el trofeo de la NHL (hockey sobre hielo). Se entrega desde 1893; Montreal Canadiens es el equipo con más victorias (24).', 'medium', 'In which sport is the Stanley Cup contested?', '["Basketball","Ice hockey","Baseball","American football"]'::jsonb, 'The Stanley Cup is the NHL trophy (ice hockey). It has been awarded since 1893; the Montreal Canadiens are the team with the most wins (24).'),
  ('deportes', '¿Cuántos sets debe ganar un tenista para ganar un partido a 5 sets?', '["2","3","4","5"]'::jsonb, 1, 'En Grand Slams masculinos se juega al mejor de 5 sets: hay que ganar 3. En femenino y la mayoría de torneos se juega al mejor de 3.', 'easy', 'How many sets must a player win to win a best-of-5-sets match?', '["2","3","4","5"]'::jsonb, 'Men''s Grand Slams are played to the best of 5 sets: you must win 3. Women''s and most tournaments are played to the best of 3.'),
  ('deportes', '¿En qué ciudad se celebraron los primeros JJ.OO. modernos en 1896?', '["París","Atenas","Roma","Berlín"]'::jsonb, 1, 'Los primeros JJ.OO. modernos fueron en Atenas 1896, organizados por Pierre de Coubertin. Participaron 241 atletas de 14 países.', 'medium', 'In which city were the first modern Olympics held in 1896?', '["Paris","Athens","Rome","Berlin"]'::jsonb, 'The first modern Olympics were in Athens 1896, organized by Pierre de Coubertin. 241 athletes from 14 countries took part.'),
  ('deportes', '¿Cuántos puntos vale un "try" en rugby union?', '["3","4","5","7"]'::jsonb, 2, 'Un try vale 5 puntos en rugby union. La transformación posterior añade 2 puntos más. Un drop goal o penal valen 3.', 'hard', 'How many points is a ''try'' worth in rugby union?', '["3","4","5","7"]'::jsonb, 'A try is worth 5 points in rugby union. The subsequent conversion adds 2 more points. A drop goal or penalty is worth 3.'),
  ('deportes', '¿En qué año se celebró el primer Mundial de fútbol?', '["1928","1930","1934","1938"]'::jsonb, 1, 'El primer Mundial fue Uruguay 1930. Lo ganó la selección anfitriona, Uruguay, venciendo a Argentina 4-2 en la final.', 'medium', 'In what year was the first football World Cup held?', '["1928","1930","1934","1938"]'::jsonb, 'The first World Cup was Uruguay 1930. The host nation, Uruguay, won it, beating Argentina 4-2 in the final.'),
  ('deportes', '¿Cuál es el récord mundial masculino de los 100 metros lisos?', '["9,58 s","9,69 s","9,77 s","9,85 s"]'::jsonb, 0, 'Usain Bolt corrió los 100 m en 9,58 s en Berlín 2009. Es el récord mundial vigente desde entonces.', 'medium', 'What is the men''s world record for the 100 meters?', '["9.58 s","9.69 s","9.77 s","9.85 s"]'::jsonb, 'Usain Bolt ran the 100 m in 9.58 s in Berlin 2009. It has been the world record ever since.'),
  ('deportes', '¿Con qué estilo comienza una prueba individual de estilos en natación?', '["Espalda","Braza","Mariposa","Libre"]'::jsonb, 2, 'En la prueba individual de estilos el orden es mariposa, espalda, braza y libre.', 'medium', 'Which stroke comes first in an individual medley swimming event?', '["Backstroke","Breaststroke","Butterfly","Freestyle"]'::jsonb, 'In the individual medley, the order is butterfly, backstroke, breaststroke and freestyle.'),
  ('deportes', '¿Cuántos hoyos tiene un campo de golf estándar?', '["9","12","18","20"]'::jsonb, 2, 'Un campo de golf estándar tiene 18 hoyos. Hay también campos de 9 que se juegan dos veces para completar una vuelta.', 'easy', 'How many holes does a standard golf course have?', '["9","12","18","20"]'::jsonb, 'A standard golf course has 18 holes. There are also 9-hole courses played twice to complete a round.'),
  ('deportes', '¿Qué club ganó las cinco primeras Copas de Europa de fútbol consecutivas?', '["Benfica","Real Madrid","Milan","Bayern de Múnich"]'::jsonb, 1, 'El Real Madrid ganó las cinco primeras ediciones de la Copa de Europa, de 1956 a 1960.', 'medium', 'Which club won the first five European Cups in football consecutively?', '["Benfica","Real Madrid","AC Milan","Bayern Munich"]'::jsonb, 'Real Madrid won the first five editions of the European Cup, from 1956 through 1960.'),
  ('deportes', '¿En qué deporte destacó Diego Maradona?', '["Boxeo","Fútbol","Tenis","Baloncesto"]'::jsonb, 1, 'Diego Armando Maradona (1960-2020) fue un futbolista argentino, considerado uno de los mejores de la historia. Campeón del Mundo en 1986.', 'easy', 'In which sport did Diego Maradona excel?', '["Boxing","Football","Tennis","Basketball"]'::jsonb, 'Diego Armando Maradona (1960-2020) was an Argentine footballer, considered one of the best in history. World champion in 1986.'),
  ('deportes', '¿Cuántos miembros tiene un equipo de voleibol en cancha?', '["5","6","7","8"]'::jsonb, 1, 'En voleibol juegan 6 por equipo en cancha. El deporte fue inventado por William G. Morgan en 1895 en Massachusetts.', 'easy', 'How many members does a volleyball team have on the court?', '["5","6","7","8"]'::jsonb, 'In volleyball, 6 per team play on the court. The sport was invented by William G. Morgan in 1895 in Massachusetts.'),
  ('deportes', '¿Quién ganó el Tour de Francia 7 veces seguidas (luego anulados)?', '["Miguel Indurain","Lance Armstrong","Chris Froome","Bernard Hinault"]'::jsonb, 1, 'Lance Armstrong ganó 7 Tours consecutivos (1999-2005), pero fueron desposeídos en 2012 por dopaje sistemático con EPO.', 'medium', 'Who won the Tour de France 7 times in a row (later annulled)?', '["Miguel Indurain","Lance Armstrong","Chris Froome","Bernard Hinault"]'::jsonb, 'Lance Armstrong won 7 consecutive Tours (1999-2005), but they were stripped in 2012 for systematic doping with EPO.'),
  ('deportes', '¿Qué selección ganó el Mundial de fútbol 2022 en Qatar?', '["Francia","Argentina","Brasil","Croacia"]'::jsonb, 1, 'Argentina ganó el Mundial 2022 venciendo a Francia en penaltis tras un 3-3. Fue el tercer título mundial de la albiceleste.', 'easy', 'Which team won the 2022 World Cup in Qatar?', '["France","Argentina","Brazil","Croatia"]'::jsonb, 'Argentina won the 2022 World Cup, beating France on penalties after a 3-3 draw. It was Argentina''s third world title.'),
  ('deportes', '¿Quién marcó nueve goles en la Eurocopa de 1984, récord para una sola edición?', '["Gerd Müller","Michel Platini","Marco van Basten","Cristiano Ronaldo"]'::jsonb, 1, 'Michel Platini marcó nueve goles con Francia en cinco partidos de la Eurocopa de 1984.', 'hard', 'Who scored nine goals at Euro 1984, the record for a single tournament?', '["Gerd Müller","Michel Platini","Marco van Basten","Cristiano Ronaldo"]'::jsonb, 'Michel Platini scored nine goals for France in five matches at Euro 1984.'),
  ('deportes', '¿Cuántos puntos vale una canasta de tres en baloncesto?', '["2","3","4","5"]'::jsonb, 1, 'Un tiro desde más allá de la línea de tres puntos vale 3. Dentro vale 2 y un tiro libre vale 1.', 'easy', 'How many points is a three-pointer worth in basketball?', '["2","3","4","5"]'::jsonb, 'A shot from beyond the three-point line is worth 3. Inside it is worth 2 and a free throw is worth 1.'),
  ('deportes', '¿En qué año debutaron los JJ.OO. de Invierno?', '["1908","1916","1924","1936"]'::jsonb, 2, 'Los primeros JJ.OO. de Invierno fueron en Chamonix (Francia) en 1924. Se celebraban el mismo año que los de verano hasta 1992.', 'hard', 'In what year did the Winter Olympics debut?', '["1908","1916","1924","1936"]'::jsonb, 'The first Winter Olympics were in Chamonix (France) in 1924. They were held in the same year as the Summer Games until 1992.'),
  ('deportes', '¿Qué país inventó el judo?', '["China","Corea","Japón","Tailandia"]'::jsonb, 2, 'El judo lo creó Jigoro Kano en Japón en 1882, basándose en el jiu-jitsu tradicional. Fue olímpico por primera vez en Tokio 1964.', 'medium', 'Which country invented judo?', '["China","Korea","Japan","Thailand"]'::jsonb, 'Judo was created by Jigoro Kano in Japan in 1882, based on traditional jiu-jitsu. It was first Olympic at Tokyo 1964.'),
  ('deportes', '¿Cuántos km recorren los corredores de Fórmula 1 en una carrera estándar?', '["200 km","305 km","450 km","500 km"]'::jsonb, 1, 'Una carrera de F1 dura ~305 km (Mónaco es la excepción con 260). El límite máximo son 2 horas de competición.', 'medium', 'How many km do Formula 1 racers cover in a standard race?', '["200 km","305 km","450 km","500 km"]'::jsonb, 'An F1 race is ~305 km long (Monaco is the exception at 260). The maximum time limit is 2 hours of competition.'),
  ('deportes', '¿De qué color es la camiseta del líder de la Vuelta a España?', '["Amarilla","Rosa","Roja","Azul"]'::jsonb, 2, 'El líder de la Vuelta lleva el maillot rojo desde 2010. Antes era amarillo, oro u otros colores. En el Tour es amarillo y en el Giro rosa.', 'medium', 'What color is the leader''s jersey in the Vuelta a España?', '["Yellow","Pink","Red","Blue"]'::jsonb, 'The Vuelta leader has worn the red jersey since 2010. Before it was yellow, gold or other colors. In the Tour it is yellow and in the Giro pink.'),
  ('deportes', '¿Qué atleta dio nombre a la técnica de salto de altura llamada Fosbury Flop?', '["Bob Beamon","Dick Fosbury","Javier Sotomayor","Valeriy Brumel"]'::jsonb, 1, 'Dick Fosbury popularizó su salto de espaldas al listón al ganar el oro olímpico en 1968.', 'medium', 'Which athlete gave his name to the high-jump technique called the Fosbury Flop?', '["Bob Beamon","Dick Fosbury","Javier Sotomayor","Valeriy Brumel"]'::jsonb, 'Dick Fosbury popularized his back-first technique when he won Olympic gold in 1968.'),
  ('deportes', '¿En qué año debutó el fútbol femenino en los JJ.OO.?', '["1992","1996","2000","2004"]'::jsonb, 1, 'El fútbol femenino debutó en Atlanta 1996, donde Estados Unidos ganó el oro. El masculino debutó en París 1900.', 'hard', 'In what year did women''s football debut at the Olympics?', '["1992","1996","2000","2004"]'::jsonb, 'Women''s football debuted at Atlanta 1996, where the United States won gold. Men''s football debuted at Paris 1900.'),
  ('deportes', '¿Cuántos minutos dura un partido de fútbol reglamentario?', '["80","90","100","120"]'::jsonb, 1, 'Un partido dura 90 minutos (2 tiempos de 45), con un descanso de 15 minutos. El árbitro añade tiempo por interrupciones.', 'easy', 'How many minutes does a regulation football match last?', '["80","90","100","120"]'::jsonb, 'A match lasts 90 minutes (2 halves of 45), with a 15-minute break. The referee adds time for stoppages.'),
  ('deportes', '¿De qué lugar inglés tomó su nombre moderno el bádminton?', '["Wembley Stadium","Badminton House","Wimbledon Common","Lord’s Cricket Ground"]'::jsonb, 1, 'El juego recibió su nombre de Badminton House, residencia del duque de Beaufort en Gloucestershire.', 'hard', 'Which English place gave badminton its modern name?', '["Wembley Stadium","Badminton House","Wimbledon Common","Lord’s Cricket Ground"]'::jsonb, 'The game took its name from Badminton House, the Duke of Beaufort’s estate in Gloucestershire.'),
  ('deportes', '¿Cuántos puntos suma un home run en béisbol?', '["1","2","3","Depende"]'::jsonb, 3, 'Un home run vale los puntos correspondientes a los corredores que lleguen al home. Con bases llenas, son 4 puntos (grand slam).', 'medium', 'How many points does a home run add in baseball?', '["1","2","3","It depends"]'::jsonb, 'A home run is worth the points corresponding to the runners who reach home. With bases loaded, it is 4 points (a grand slam).'),
  ('deportes', '¿Qué selección ganó la Eurocopa 2020 (celebrada en 2021)?', '["Inglaterra","Italia","Francia","España"]'::jsonb, 1, 'Italia ganó la Eurocopa 2020 venciendo a Inglaterra en penaltis en Wembley. Roberto Mancini fue el seleccionador.', 'medium', 'Which team won Euro 2020 (held in 2021)?', '["England","Italy","France","Spain"]'::jsonb, 'Italy won Euro 2020, beating England on penalties at Wembley. Roberto Mancini was the manager.'),
  ('deportes', '¿Cuánto pesa un balón oficial de fútbol?', '["350-380 g","410-450 g","500-550 g","600 g"]'::jsonb, 1, 'Un balón oficial pesa entre 410 y 450 gramos al inicio del partido, según las reglas de la FIFA.', 'hard', 'How much does an official football weigh?', '["350-380 g","410-450 g","500-550 g","600 g"]'::jsonb, 'An official football weighs between 410 and 450 grams at the start of the match, according to FIFA rules.'),
  ('deportes', '¿Qué pieza de ajedrez puede capturar “al paso”?', '["El caballo","El peón","La torre","El alfil"]'::jsonb, 1, 'La captura al paso solo puede realizarla un peón inmediatamente después de que otro avance dos casillas desde su posición inicial.', 'medium', 'Which chess piece can capture en passant?', '["Knight","Pawn","Rook","Bishop"]'::jsonb, 'Only a pawn can capture en passant, immediately after an opposing pawn advances two squares from its starting position.'),
  ('deportes', '¿Cuánto mide una piscina olímpica de largo?', '["25 metros","40 metros","50 metros","100 metros"]'::jsonb, 2, 'Una piscina olímpica de curso largo mide 50 metros; las piscinas de curso corto miden 25.', 'easy', 'How long is an Olympic swimming pool?', '["25 metres","40 metres","50 metres","100 metres"]'::jsonb, 'An Olympic long-course pool is 50 metres long; short-course pools are 25 metres.'),
  ('deportes', '¿Qué jugador de voleibol viste una camiseta de color distinto a la de sus compañeros?', '["El líbero","El colocador","El opuesto","El capitán"]'::jsonb, 0, 'El líbero lleva una equipación que contrasta con la del resto del equipo para que los árbitros puedan identificar sus sustituciones y restricciones.', 'easy', 'Which volleyball player wears a jersey of a different colour from their teammates?', '["The libero","The setter","The opposite hitter","The captain"]'::jsonb, 'The libero wears a contrasting uniform so officials can identify the player’s substitutions and restrictions.'),
  ('deportes', '¿En qué año se celebró el primer Súper Bowl?', '["1960","1967","1970","1975"]'::jsonb, 1, 'El primer Súper Bowl fue en enero de 1967. Los Green Bay Packers vencieron a los Kansas City Chiefs 35-10.', 'hard', 'In what year was the first Super Bowl held?', '["1960","1967","1970","1975"]'::jsonb, 'The first Super Bowl was in January 1967. The Green Bay Packers beat the Kansas City Chiefs 35-10.'),
  ('deportes', '¿Cuál es el deporte nacional de verano de Canadá según su legislación?', '["Lacrosse","Hockey sobre hielo","Curling","Béisbol"]'::jsonb, 0, 'La ley canadiense reconoce el lacrosse como deporte nacional de verano y el hockey sobre hielo como deporte nacional de invierno.', 'medium', 'What is Canada’s national summer sport under its legislation?', '["Lacrosse","Ice hockey","Curling","Baseball"]'::jsonb, 'Canadian law recognizes lacrosse as the national summer sport and ice hockey as the national winter sport.'),
  ('deportes', '¿Cuánto mide una vuelta por la calle interior de una pista estándar de atletismo?', '["300 metros","400 metros","440 metros","500 metros"]'::jsonb, 1, 'Una pista estándar al aire libre mide 400 metros por la calle interior.', 'easy', 'How long is one lap of the inside lane on a standard athletics track?', '["300 metres","400 metres","440 metres","500 metres"]'::jsonb, 'A standard outdoor athletics track measures 400 metres around the inside lane.'),
  ('deportes', '¿En qué año Roger Bannister bajó por primera vez de 4 minutos en la milla?', '["1948","1952","1954","1960"]'::jsonb, 2, 'Roger Bannister fue el primero en correr la milla bajo 4 minutos (3:59,4) el 6 de mayo de 1954 en Oxford.', 'hard', 'In what year did Roger Bannister first break 4 minutes in the mile?', '["1948","1952","1954","1960"]'::jsonb, 'Roger Bannister was the first to run the mile under 4 minutes (3:59.4) on 6 May 1954 in Oxford.'),
  ('deportes', '¿Cuántas medallas de oro ganó Mark Spitz en Múnich 1972?', '["5","6","7","8"]'::jsonb, 2, 'Mark Spitz ganó 7 oros en natación en Múnich 1972, récord que solo superó Michael Phelps con 8 en Pekín 2008.', 'hard', 'How many gold medals did Mark Spitz win at Munich 1972?', '["5","6","7","8"]'::jsonb, 'Mark Spitz won 7 swimming golds at Munich 1972, a record only surpassed by Michael Phelps with 8 at Beijing 2008.'),
  ('deportes', '¿Qué jugador de la NBA tiene más anillos?', '["Michael Jordan","Bill Russell","LeBron James","Kareem Abdul-Jabbar"]'::jsonb, 1, 'Bill Russell ganó 11 anillos con los Boston Celtics entre 1957 y 1969. Michael Jordan ganó 6 con los Chicago Bulls.', 'hard', 'Which NBA player has the most rings?', '["Michael Jordan","Bill Russell","LeBron James","Kareem Abdul-Jabbar"]'::jsonb, 'Bill Russell won 11 rings with the Boston Celtics between 1957 and 1969. Michael Jordan won 6 with the Chicago Bulls.'),
  ('deportes', '¿Qué deporte se practica en Wimbledon?', '["Golf","Cricket","Tenis","Rugby"]'::jsonb, 2, 'Wimbledon es el torneo de tenis más prestigioso, fundado en 1877. Se juega sobre hierba y los jugadores visten obligatoriamente de blanco.', 'easy', 'Which sport is played at Wimbledon?', '["Golf","Cricket","Tennis","Rugby"]'::jsonb, 'Wimbledon is the most prestigious tennis tournament, founded in 1877. It is played on grass and players are required to wear white.'),
  ('deportes', '¿Cuántos puntos suma un touchdown en fútbol americano?', '["3","6","7","9"]'::jsonb, 1, 'Un touchdown vale 6 puntos. Después se puede convertir 1 punto extra (patada) o 2 (jugada desde la yarda 2).', 'medium', 'How many points does a touchdown add in American football?', '["3","6","7","9"]'::jsonb, 'A touchdown is worth 6 points. Afterward you can convert 1 extra point (a kick) or 2 (a play from the 2-yard line).'),
  ('deportes', '¿Quién es el máximo goleador histórico del Mundial?', '["Pelé","Ronaldo","Klose","Müller"]'::jsonb, 2, 'El alemán Miroslav Klose lidera con 16 goles en Mundiales (2002-2014). Ronaldo Nazário marcó 15 y Müller 14.', 'hard', 'Who is the all-time top scorer at the World Cup?', '["Pelé","Ronaldo","Klose","Müller"]'::jsonb, 'Germany''s Miroslav Klose leads with 16 World Cup goals (2002-2014). Ronaldo Nazário scored 15 and Müller 14.'),
  ('deportes', '¿Qué jugador es apodado "La Pulga"?', '["Cristiano Ronaldo","Neymar","Lionel Messi","Mbappé"]'::jsonb, 2, 'Lionel Messi recibe ese apodo por su baja estatura y agilidad. Ha ganado 8 Balones de Oro, récord absoluto.', 'easy', 'Which player is nicknamed ''La Pulga'' (The Flea)?', '["Cristiano Ronaldo","Neymar","Lionel Messi","Mbappé"]'::jsonb, 'Lionel Messi gets this nickname for his short stature and agility. He has won 8 Ballon d''Or awards, an all-time record.'),
  ('deportes', '¿Cuántos puntos vale un drop goal en rugby union?', '["2","3","4","5"]'::jsonb, 1, 'En rugby union, un drop goal vale tres puntos y se consigue pateando el balón tras botarlo durante el juego abierto.', 'medium', 'How many points is a drop goal worth in rugby union?', '["2","3","4","5"]'::jsonb, 'In rugby union, a drop goal is worth three points and is scored by kicking the ball after it bounces in open play.'),
  ('deportes', '¿Cuántos jugadores tiene un equipo de waterpolo en cancha?', '["5","6","7","8"]'::jsonb, 2, 'En waterpolo juegan 7 por equipo (6 más portero). Los partidos se dividen en 4 cuartos de 8 minutos.', 'hard', 'How many players does a water polo team have in play?', '["5","6","7","8"]'::jsonb, 'In water polo, 7 per team play (6 plus the goalkeeper). Matches are divided into 4 quarters of 8 minutes.'),
  ('biologia', '¿Cuál es el órgano más grande del cuerpo humano?', '["Hígado","Pulmón","Piel","Intestino"]'::jsonb, 2, 'La piel es el órgano más extenso, con unos 2 m² y hasta 5 kg. Es la primera barrera de defensa frente al exterior.', 'easy', 'What is the largest organ in the human body?', '["Liver","Lung","Skin","Intestine"]'::jsonb, 'The skin is the largest organ, at about 2 m² and up to 5 kg. It is the first line of defense against the outside.'),
  ('biologia', '¿Qué estructuras protegen los extremos de los cromosomas?', '["Centrómeros","Telómeros","Ribosomas","Nucleosomas"]'::jsonb, 1, 'Los telómeros son secuencias repetitivas que protegen los extremos de los cromosomas frente al deterioro y las fusiones.', 'medium', 'Which structures protect the ends of chromosomes?', '["Centromeres","Telomeres","Ribosomes","Nucleosomes"]'::jsonb, 'Telomeres are repetitive sequences that protect chromosome ends from deterioration and fusion.'),
  ('biologia', '¿Qué orgánulo se conoce como la "central energética" de la célula?', '["Núcleo","Mitocondria","Ribosoma","Lisosoma"]'::jsonb, 1, 'Las mitocondrias generan ATP mediante respiración celular. Tienen su propio ADN, herencia evolutiva de una bacteria simbiótica.', 'easy', 'Which organelle is known as the ''powerhouse'' of the cell?', '["Nucleus","Mitochondrion","Ribosome","Lysosome"]'::jsonb, 'Mitochondria generate ATP through cellular respiration. They have their own DNA, an evolutionary legacy of a symbiotic bacterium.'),
  ('biologia', '¿Cuántos nucleótidos forman un codón del código genético?', '["2","3","4","5"]'::jsonb, 1, 'Cada codón contiene tres nucleótidos y normalmente especifica un aminoácido o una señal de parada.', 'medium', 'How many nucleotides make up a codon in the genetic code?', '["2","3","4","5"]'::jsonb, 'Each codon contains three nucleotides and usually specifies an amino acid or a stop signal.'),
  ('biologia', '¿Qué bases nitrogenadas forman el ADN?', '["A,T,C,G","A,U,C,G","A,T,C,U","A,U,T,G"]'::jsonb, 0, 'El ADN contiene adenina (A), timina (T), citosina (C) y guanina (G). En el ARN la timina se sustituye por uracilo (U).', 'medium', 'Which nitrogenous bases make up DNA?', '["A,T,C,G","A,U,C,G","A,T,C,U","A,U,T,G"]'::jsonb, 'DNA contains adenine (A), thymine (T), cytosine (C) and guanine (G). In RNA, thymine is replaced by uracil (U).'),
  ('biologia', '¿Cuál es la unidad básica de la vida?', '["Átomo","Molécula","Célula","Tejido"]'::jsonb, 2, 'La célula es la unidad estructural y funcional básica de los seres vivos, formulado por la teoría celular en 1839.', 'easy', 'What is the basic unit of life?', '["Atom","Molecule","Cell","Tissue"]'::jsonb, 'The cell is the basic structural and functional unit of living beings, formulated by cell theory in 1839.'),
  ('biologia', '¿Qué tipo de células no tienen núcleo definido?', '["Eucariotas","Procariotas","Animales","Vegetales"]'::jsonb, 1, 'Las procariotas (bacterias y arqueas) no tienen núcleo: su ADN flota libre en el citoplasma. Aparecieron hace ~3.500 M de años.', 'medium', 'Which type of cell has no defined nucleus?', '["Eukaryotic","Prokaryotic","Animal","Plant"]'::jsonb, 'Prokaryotes (bacteria and archaea) have no nucleus: their DNA floats freely in the cytoplasm. They appeared ~3,500 million years ago.'),
  ('biologia', '¿Cuál es el sistema responsable de defender al cuerpo de infecciones?', '["Endocrino","Inmunitario","Nervioso","Digestivo"]'::jsonb, 1, 'El sistema inmunitario incluye linfocitos, anticuerpos y otros componentes que identifican y eliminan patógenos.', 'easy', 'Which system is responsible for defending the body from infections?', '["Endocrine","Immune","Nervous","Digestive"]'::jsonb, 'The immune system includes lymphocytes, antibodies and other components that identify and eliminate pathogens.'),
  ('biologia', '¿Qué proceso permite a las plantas convertir luz en energía?', '["Respiración","Fotosíntesis","Fermentación","Transpiración"]'::jsonb, 1, 'La fotosíntesis convierte CO₂ y agua en glucosa y O₂ usando la energía solar. Ocurre principalmente en los cloroplastos.', 'easy', 'Which process allows plants to convert light into energy?', '["Respiration","Photosynthesis","Fermentation","Transpiration"]'::jsonb, 'Photosynthesis converts CO₂ and water into glucose and O₂ using solar energy. It occurs mainly in the chloroplasts.'),
  ('biologia', '¿Qué animal tiene el corazón más grande del planeta?', '["Elefante africano","Jirafa","Ballena azul","Tiburón ballena"]'::jsonb, 2, 'El corazón de la ballena azul puede pesar más de 180 kg y bombea 220 litros de sangre por latido. Es el animal más grande conocido.', 'medium', 'Which animal has the largest heart on the planet?', '["African elephant","Giraffe","Blue whale","Whale shark"]'::jsonb, 'The blue whale''s heart can weigh more than 180 kg and pumps 220 liters of blood per beat. It is the largest known animal.'),
  ('biologia', '¿Qué científica impulsó la teoría endosimbiótica moderna?', '["Rachel Carson","Lynn Margulis","Barbara McClintock","Jane Goodall"]'::jsonb, 1, 'Lynn Margulis desarrolló la teoría de que mitocondrias y cloroplastos proceden de bacterias incorporadas por células ancestrales.', 'hard', 'Which scientist advanced the modern endosymbiotic theory?', '["Rachel Carson","Lynn Margulis","Barbara McClintock","Jane Goodall"]'::jsonb, 'Lynn Margulis developed the theory that mitochondria and chloroplasts descend from bacteria engulfed by ancestral cells.'),
  ('biologia', '¿Cuál es la unidad contráctil básica del músculo estriado?', '["Neurona","Sarcómero","Tendón","Osteona"]'::jsonb, 1, 'El sarcómero es el segmento repetitivo donde los filamentos de actina y miosina producen la contracción muscular.', 'medium', 'What is the basic contractile unit of striated muscle?', '["Neuron","Sarcomere","Tendon","Osteon"]'::jsonb, 'The sarcomere is the repeating segment where actin and myosin filaments produce muscle contraction.'),
  ('biologia', '¿Qué tipo de sangre se considera donante universal?', '["A+","O-","AB+","B+"]'::jsonb, 1, 'O negativo no tiene antígenos A, B ni Rh, así que puede transfundirse a cualquier persona en emergencias. AB+ es el receptor universal.', 'medium', 'Which blood type is considered the universal donor?', '["A+","O-","AB+","B+"]'::jsonb, 'O negative has no A, B or Rh antigens, so it can be transfused to anyone in emergencies. AB+ is the universal recipient.'),
  ('biologia', '¿Cuántas cámaras tiene el corazón humano?', '["2","3","4","5"]'::jsonb, 2, 'El corazón tiene 4 cámaras: 2 aurículas (arriba) y 2 ventrículos (abajo). La sangre fluye en circuitos pulmonar y sistémico.', 'easy', 'How many chambers does the human heart have?', '["2","3","4","5"]'::jsonb, 'The heart has 4 chambers: 2 atria (top) and 2 ventricles (bottom). Blood flows in pulmonary and systemic circuits.'),
  ('biologia', '¿En qué orgánulo se sintetizan las proteínas?', '["Núcleo","Mitocondria","Ribosoma","Cloroplasto"]'::jsonb, 2, 'Los ribosomas sintetizan proteínas leyendo el ARN mensajero (traducción). Pueden estar libres o adheridos al retículo endoplasmático.', 'medium', 'In which organelle are proteins synthesized?', '["Nucleus","Mitochondrion","Ribosome","Chloroplast"]'::jsonb, 'Ribosomes synthesize proteins by reading messenger RNA (translation). They can be free or attached to the endoplasmic reticulum.'),
  ('biologia', '¿Cuál es el grupo sanguíneo receptor universal?', '["O-","O+","AB+","A+"]'::jsonb, 2, 'AB+ puede recibir sangre de cualquier grupo, porque tiene antígenos A, B y Rh y no produce anticuerpos contra ellos.', 'medium', 'Which is the universal recipient blood group?', '["O-","O+","AB+","A+"]'::jsonb, 'AB+ can receive blood from any group, because it has A, B and Rh antigens and produces no antibodies against them.'),
  ('biologia', '¿Qué neurotransmisor está relacionado con el placer y la recompensa?', '["Serotonina","Dopamina","GABA","Glutamato"]'::jsonb, 1, 'La dopamina regula motivación, recompensa y placer. Su déficit se asocia al Parkinson y su exceso a esquizofrenia.', 'medium', 'Which neurotransmitter is related to pleasure and reward?', '["Serotonin","Dopamine","GABA","Glutamate"]'::jsonb, 'Dopamine regulates motivation, reward and pleasure. Its deficit is associated with Parkinson''s and its excess with schizophrenia.'),
  ('biologia', '¿Cuál es el animal terrestre más rápido?', '["León","Guepardo","Antílope","Caballo"]'::jsonb, 1, 'El guepardo alcanza 110 km/h en aceleraciones cortas. Su largo cuerpo y garras semi-retráctiles son adaptaciones a la velocidad.', 'easy', 'Which is the fastest land animal?', '["Lion","Cheetah","Antelope","Horse"]'::jsonb, 'The cheetah reaches 110 km/h in short bursts. Its long body and semi-retractable claws are adaptations for speed.'),
  ('biologia', '¿Qué ácido predomina en el jugo gástrico?', '["Sulfúrico","Clorhídrico","Nítrico","Cítrico"]'::jsonb, 1, 'El ácido clorhídrico (HCl) en el estómago tiene pH 1-2 y activa la pepsina para digerir proteínas.', 'medium', 'Which acid predominates in gastric juice?', '["Sulfuric","Hydrochloric","Nitric","Citric"]'::jsonb, 'Hydrochloric acid (HCl) in the stomach has a pH of 1-2 and activates pepsin to digest proteins.'),
  ('biologia', '¿Cuántas patas tiene un insecto?', '["4","6","8","10"]'::jsonb, 1, 'Los insectos tienen 6 patas (3 pares), divididas en 3 segmentos corporales: cabeza, tórax y abdomen. Los arácnidos tienen 8.', 'easy', 'How many legs does an insect have?', '["4","6","8","10"]'::jsonb, 'Insects have 6 legs (3 pairs), divided into 3 body segments: head, thorax and abdomen. Arachnids have 8.'),
  ('biologia', '¿En qué parte del cerebro se controla el equilibrio?', '["Cerebro","Cerebelo","Bulbo raquídeo","Hipotálamo"]'::jsonb, 1, 'El cerebelo coordina el movimiento, equilibrio y postura. Está en la parte posterior del encéfalo.', 'medium', 'In which part of the brain is balance controlled?', '["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"]'::jsonb, 'The cerebellum coordinates movement, balance and posture. It is at the back of the brain.'),
  ('biologia', '¿Cuál es el hueso más largo del cuerpo humano?', '["Tibia","Fémur","Húmero","Cúbito"]'::jsonb, 1, 'El fémur (muslo) mide ~46 cm en un adulto medio. Es también el hueso más fuerte: soporta cargas de hasta 1.500 kg.', 'easy', 'Which is the longest bone in the human body?', '["Tibia","Femur","Humerus","Ulna"]'::jsonb, 'The femur (thigh) measures ~46 cm in an average adult. It is also the strongest bone: it supports loads of up to 1,500 kg.'),
  ('biologia', '¿Cuántas patas tienen las arañas?', '["6","8","10","12"]'::jsonb, 1, 'Las arañas tienen 8 patas, característica de los arácnidos. Tienen el cuerpo dividido en cefalotórax y abdomen.', 'easy', 'How many legs do spiders have?', '["6","8","10","12"]'::jsonb, 'Spiders have 8 legs, a characteristic of arachnids. Their body is divided into a cephalothorax and abdomen.'),
  ('biologia', '¿Qué órgano filtra la sangre y produce orina?', '["Hígado","Vejiga","Riñón","Páncreas"]'::jsonb, 2, 'Los riñones filtran ~180 litros de sangre al día, eliminando residuos y regulando agua y electrolitos.', 'easy', 'Which organ filters blood and produces urine?', '["Liver","Bladder","Kidney","Pancreas"]'::jsonb, 'The kidneys filter ~180 liters of blood a day, eliminating waste and regulating water and electrolytes.'),
  ('biologia', '¿Cómo se llama el proceso de división celular que produce gametos?', '["Mitosis","Meiosis","Apoptosis","Citocinesis"]'::jsonb, 1, 'La meiosis produce 4 células haploides a partir de una diploide, con recombinación genética. Es la base de la reproducción sexual.', 'medium', 'What is the name of the cell division process that produces gametes?', '["Mitosis","Meiosis","Apoptosis","Cytokinesis"]'::jsonb, 'Meiosis produces 4 haploid cells from one diploid, with genetic recombination. It is the basis of sexual reproduction.'),
  ('biologia', '¿Qué es un plásmido bacteriano?', '["Una pared celular","Una pequeña molécula de ADN extracromosómico","Un virus con envoltura","Un tipo de ribosoma"]'::jsonb, 1, 'Los plásmidos son moléculas de ADN que se replican aparte del cromosoma bacteriano y pueden portar genes de resistencia.', 'medium', 'What is a bacterial plasmid?', '["A cell wall","A small extrachromosomal DNA molecule","An enveloped virus","A type of ribosome"]'::jsonb, 'Plasmids are DNA molecules that replicate separately from the bacterial chromosome and may carry resistance genes.'),
  ('biologia', '¿Cuántos litros de sangre tiene un adulto medio?', '["3","5","7","10"]'::jsonb, 1, 'Un adulto tiene unos 5 litros de sangre (7-8% del peso corporal). Una pérdida superior al 20% puede ser mortal.', 'medium', 'How many liters of blood does an average adult have?', '["3","5","7","10"]'::jsonb, 'An adult has about 5 liters of blood (7-8% of body weight). A loss of more than 20% can be fatal.'),
  ('biologia', '¿Qué pigmento da el color verde a las plantas?', '["Caroteno","Clorofila","Antocianina","Melanina"]'::jsonb, 1, 'La clorofila absorbe luz roja y azul y refleja la verde. Es esencial para la fotosíntesis y reside en los cloroplastos.', 'easy', 'Which pigment gives plants their green color?', '["Carotene","Chlorophyll","Anthocyanin","Melanin"]'::jsonb, 'Chlorophyll absorbs red and blue light and reflects green. It is essential for photosynthesis and resides in the chloroplasts.'),
  ('biologia', '¿Qué glándula regula el metabolismo mediante hormonas tiroideas?', '["Hipófisis","Tiroides","Suprarrenal","Páncreas"]'::jsonb, 1, 'La tiroides secreta T3 y T4 que regulan el metabolismo basal. Su mal funcionamiento causa hipo- o hipertiroidismo.', 'medium', 'Which gland regulates metabolism through thyroid hormones?', '["Pituitary","Thyroid","Adrenal","Pancreas"]'::jsonb, 'The thyroid secretes T3 and T4, which regulate basal metabolism. Its malfunction causes hypo- or hyperthyroidism.'),
  ('biologia', '¿Quiénes descubrieron la estructura del ADN en 1953?', '["Mendel y Morgan","Watson y Crick","Pasteur y Koch","Darwin y Wallace"]'::jsonb, 1, 'Watson y Crick propusieron la doble hélice en 1953, basándose en los datos de difracción de Rosalind Franklin. Premio Nobel 1962.', 'medium', 'Who discovered the structure of DNA in 1953?', '["Mendel and Morgan","Watson and Crick","Pasteur and Koch","Darwin and Wallace"]'::jsonb, 'Watson and Crick proposed the double helix in 1953, based on Rosalind Franklin''s diffraction data. Nobel Prize 1962.'),
  ('biologia', '¿Cuántos litros de aire respira un humano al día (media)?', '["1.000","5.000","11.000","30.000"]'::jsonb, 2, 'Un adulto respira ~11.000 litros de aire al día (12-16 respiraciones por minuto, 500 ml cada una).', 'hard', 'How many liters of air does a human breathe per day (average)?', '["1,000","5,000","11,000","30,000"]'::jsonb, 'An adult breathes ~11,000 liters of air per day (12-16 breaths per minute, 500 ml each).'),
  ('biologia', '¿Qué órgano produce la insulina?', '["Hígado","Riñón","Páncreas","Tiroides"]'::jsonb, 2, 'El páncreas, a través de los islotes de Langerhans, produce insulina (regula glucosa) y glucagón. Su disfunción causa diabetes.', 'medium', 'Which organ produces insulin?', '["Liver","Kidney","Pancreas","Thyroid"]'::jsonb, 'The pancreas, through the islets of Langerhans, produces insulin (regulates glucose) and glucagon. Its dysfunction causes diabetes.'),
  ('biologia', '¿Cuál es la unidad básica del sistema nervioso?', '["Neurona","Sinapsis","Axón","Mielina"]'::jsonb, 0, 'La neurona transmite señales eléctricas y químicas. El cerebro humano tiene unas 86.000 millones de neuronas.', 'easy', 'What is the basic unit of the nervous system?', '["Neuron","Synapse","Axon","Myelin"]'::jsonb, 'The neuron transmits electrical and chemical signals. The human brain has about 86 billion neurons.'),
  ('biologia', '¿Qué reino taxonómico incluye a los hongos?', '["Plantae","Fungi","Animalia","Protista"]'::jsonb, 1, 'Los hongos forman su propio reino, Fungi. No son plantas: no hacen fotosíntesis y su pared celular es de quitina.', 'medium', 'Which taxonomic kingdom includes fungi?', '["Plantae","Fungi","Animalia","Protista"]'::jsonb, 'Fungi form their own kingdom, Fungi. They are not plants: they do not photosynthesize and their cell wall is made of chitin.'),
  ('biologia', '¿Cuántos sentidos tiene tradicionalmente el ser humano?', '["4","5","6","7"]'::jsonb, 1, 'Tradicionalmente se reconocen 5: vista, oído, olfato, gusto y tacto. La ciencia moderna añade equilibrio, propiocepción, etc.', 'easy', 'How many senses does the human being traditionally have?', '["4","5","6","7"]'::jsonb, 'Traditionally 5 are recognized: sight, hearing, smell, taste and touch. Modern science adds balance, proprioception, etc.'),
  ('biologia', '¿Cuál es el animal con el mayor cerebro?', '["Humano","Cachalote","Elefante","Delfín"]'::jsonb, 1, 'El cachalote tiene el cerebro más pesado: hasta 8 kg. El humano tiene ~1,4 kg pero la mayor relación cerebro/cuerpo entre los grandes.', 'medium', 'Which animal has the largest brain?', '["Human","Sperm whale","Elephant","Dolphin"]'::jsonb, 'The sperm whale has the heaviest brain: up to 8 kg. The human has ~1.4 kg but the highest brain/body ratio among the large ones.'),
  ('biologia', '¿Qué tipo de raíz tiene la zanahoria?', '["Fibrosa","Pivotante","Adventicia","Aérea"]'::jsonb, 1, 'La zanahoria tiene raíz pivotante, axonomorfa, que crece engrosada como reserva de azúcares (especialmente carotenos).', 'hard', 'What type of root does the carrot have?', '["Fibrous","Taproot","Adventitious","Aerial"]'::jsonb, 'The carrot has a taproot (axonomorphic), which grows thickened as a sugar reserve (especially carotenes).'),
  ('biologia', '¿Qué tipo de reproducción producen las bacterias?', '["Sexual","Asexual","Vivípara","Ovípara"]'::jsonb, 1, 'Las bacterias se reproducen por fisión binaria (asexual), duplicando su ADN y dividiéndose en dos células hijas idénticas.', 'medium', 'What type of reproduction do bacteria have?', '["Sexual","Asexual","Viviparous","Oviparous"]'::jsonb, 'Bacteria reproduce by binary fission (asexual), duplicating their DNA and dividing into two identical daughter cells.'),
  ('biologia', '¿Cuántas vértebras tiene la columna humana?', '["24","33","36","40"]'::jsonb, 1, 'La columna tiene 33 vértebras: 7 cervicales, 12 dorsales, 5 lumbares, 5 sacras (fusionadas) y 4 coccígeas (fusionadas).', 'medium', 'How many vertebrae does the human spine have?', '["24","33","36","40"]'::jsonb, 'The spine has 33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, 5 sacral (fused) and 4 coccygeal (fused).'),
  ('biologia', '¿Qué función cumplen los glóbulos rojos?', '["Defender de infecciones","Coagular sangre","Transportar O₂","Producir hormonas"]'::jsonb, 2, 'Los eritrocitos transportan O₂ desde los pulmones a los tejidos gracias a la hemoglobina, que contiene hierro.', 'easy', 'What function do red blood cells perform?', '["Defend from infections","Clot blood","Transport O₂","Produce hormones"]'::jsonb, 'Erythrocytes transport O₂ from the lungs to the tissues thanks to hemoglobin, which contains iron.'),
  ('biologia', '¿Qué abertura comparten los aparatos digestivo, urinario y reproductor de muchas aves?', '["Espiráculo","Cloaca","Opérculo","Píloro"]'::jsonb, 1, 'La cloaca es una cavidad común presente en aves y otros vertebrados para la salida de varios sistemas corporales.', 'medium', 'Which opening is shared by the digestive, urinary and reproductive systems of many birds?', '["Spiracle","Cloaca","Operculum","Pylorus"]'::jsonb, 'The cloaca is a common chamber in birds and other vertebrates used by several body systems.'),
  ('biologia', '¿En qué fase del ciclo celular se replica el ADN?', '["G1","S","G2","M"]'::jsonb, 1, 'La replicación del ADN ocurre en la fase S (síntesis), entre G1 y G2 de la interfase. M es la fase mitótica.', 'hard', 'In which phase of the cell cycle is DNA replicated?', '["G1","S","G2","M"]'::jsonb, 'DNA replication occurs in the S (synthesis) phase, between G1 and G2 of interphase. M is the mitotic phase.'),
  ('biologia', '¿Qué organismos forman normalmente un liquen?', '["Un hongo y un alga o cianobacteria","Dos especies de musgo","Una bacteria y un virus","Un helecho y un hongo"]'::jsonb, 0, 'Un liquen es una asociación estable entre un hongo y un organismo fotosintético, que puede ser un alga o una cianobacteria.', 'medium', 'Which organisms normally form a lichen?', '["A fungus and an alga or cyanobacterium","Two moss species","A bacterium and a virus","A fern and a fungus"]'::jsonb, 'A lichen is a stable association between a fungus and a photosynthetic organism, either an alga or a cyanobacterium.'),
  ('biologia', '¿Qué tipo de planta es el helecho?', '["Angiosperma","Gimnosperma","Pteridofita","Briofita"]'::jsonb, 2, 'Los helechos son pteridofitas: plantas vasculares sin semillas, que se reproducen por esporas. Existen desde el Devónico.', 'hard', 'What type of plant is the fern?', '["Angiosperm","Gymnosperm","Pteridophyte","Bryophyte"]'::jsonb, 'Ferns are pteridophytes: vascular plants without seeds, which reproduce by spores. They have existed since the Devonian.'),
  ('biologia', '¿Qué animal es conocido como el "diablo de Tasmania"?', '["Una rata","Un marsupial","Un reptil","Un anfibio"]'::jsonb, 1, 'El diablo de Tasmania (Sarcophilus harrisii) es un marsupial carnívoro endémico de Tasmania. Es el mayor depredador marsupial actual.', 'medium', 'Which animal is known as the ''Tasmanian devil''?', '["A rat","A marsupial","A reptile","An amphibian"]'::jsonb, 'The Tasmanian devil (Sarcophilus harrisii) is a carnivorous marsupial endemic to Tasmania. It is the largest marsupial predator today.'),
  ('biologia', '¿Cuántos pares de costillas tiene el ser humano?', '["10","12","14","16"]'::jsonb, 1, 'El ser humano tiene 12 pares de costillas: 7 verdaderas, 3 falsas y 2 flotantes. Suman 24 huesos en total.', 'easy', 'How many pairs of ribs does a human have?', '["10","12","14","16"]'::jsonb, 'The human has 12 pairs of ribs: 7 true, 3 false and 2 floating. They add up to 24 bones in total.'),
  ('biologia', '¿Qué tejido recubre los órganos internos y forma glándulas?', '["Conectivo","Muscular","Epitelial","Nervioso"]'::jsonb, 2, 'El tejido epitelial recubre superficies (piel, mucosas) y forma glándulas exocrinas y endocrinas. Hay 4 tejidos básicos.', 'medium', 'Which tissue lines internal organs and forms glands?', '["Connective","Muscle","Epithelial","Nervous"]'::jsonb, 'Epithelial tissue covers surfaces (skin, mucous membranes) and forms exocrine and endocrine glands. There are 4 basic tissues.'),
  ('biologia', '¿Qué proceso convierte glucosa en energía (ATP) en presencia de O₂?', '["Glucólisis","Respiración aeróbica","Fermentación","Fotosíntesis"]'::jsonb, 1, 'La respiración aeróbica (ciclo de Krebs + cadena respiratoria) genera ~36-38 moléculas de ATP por glucosa en presencia de oxígeno.', 'medium', 'Which process converts glucose into energy (ATP) in the presence of O₂?', '["Glycolysis","Aerobic respiration","Fermentation","Photosynthesis"]'::jsonb, 'Aerobic respiration (Krebs cycle + respiratory chain) generates ~36-38 ATP molecules per glucose in the presence of oxygen.'),
  ('cine', '¿Cuál fue el primer largometraje animado de Disney?', '["Pinocho","Blancanieves y los siete enanitos","Fantasía","Dumbo"]'::jsonb, 1, '“Blancanieves y los siete enanitos” se estrenó en 1937 y fue el primer largometraje animado del estudio Disney.', 'easy', 'What was Disney’s first animated feature film?', '["Pinocchio","Snow White and the Seven Dwarfs","Fantasia","Dumbo"]'::jsonb, 'Snow White and the Seven Dwarfs premiered in 1937 and was Disney’s first animated feature film.'),
  ('cine', '¿Qué película ganó el primer Óscar a Mejor Película?', '["Alas","Lo que el viento se llevó","Casablanca","Ben-Hur"]'::jsonb, 0, '"Alas" (Wings, 1927), de William A. Wellman, ganó en 1929. Es la única película muda en obtener el Óscar a Mejor Película.', 'hard', 'Which film won the first Oscar for Best Picture?', '["Wings","Gone with the Wind","Casablanca","Ben-Hur"]'::jsonb, '''Wings'' (1927), by William A. Wellman, won in 1929. It is the only silent film to win the Oscar for Best Picture.'),
  ('cine', '¿Qué actor colaboró con Akira Kurosawa en películas como “Yojimbo” y “Los siete samuráis”?', '["Tatsuya Nakadai","Toshirō Mifune","Ken Takakura","Takashi Shimura"]'::jsonb, 1, 'Toshirō Mifune protagonizó dieciséis películas dirigidas por Akira Kurosawa entre 1948 y 1965.', 'hard', 'Which actor worked with Akira Kurosawa in films such as Yojimbo and Seven Samurai?', '["Tatsuya Nakadai","Toshirō Mifune","Ken Takakura","Takashi Shimura"]'::jsonb, 'Toshirō Mifune starred in sixteen films directed by Akira Kurosawa between 1948 and 1965.'),
  ('cine', '¿Qué técnica de montaje crea una discontinuidad visible al cortar dentro de un mismo plano?', '["Jump cut","Fundido encadenado","Plano secuencia","Iris"]'::jsonb, 0, 'El jump cut elimina una parte de una toma continua y produce un salto perceptible en el tiempo o la posición.', 'hard', 'Which editing technique creates a visible discontinuity by cutting within the same shot?', '["Jump cut","Dissolve","Long take","Iris shot"]'::jsonb, 'A jump cut removes part of a continuous take, producing a noticeable jump in time or position.'),
  ('cine', '¿En qué año se estrenó la primera "Star Wars"?', '["1975","1977","1979","1980"]'::jsonb, 1, 'La primera "Star Wars" (Una Nueva Esperanza) se estrenó en mayo de 1977. La dirigió George Lucas.', 'medium', 'In what year was the first ''Star Wars'' released?', '["1975","1977","1979","1980"]'::jsonb, 'The first ''Star Wars'' (A New Hope) was released in May 1977. It was directed by George Lucas.'),
  ('cine', '¿Quién es el director de "Titanic" (1997)?', '["Spielberg","Cameron","Zemeckis","Ridley Scott"]'::jsonb, 1, 'James Cameron dirigió "Titanic", que ganó 11 Óscars (récord, empatada con Ben-Hur y El Retorno del Rey).', 'easy', 'Who is the director of ''Titanic'' (1997)?', '["Spielberg","Cameron","Zemeckis","Ridley Scott"]'::jsonb, 'James Cameron directed ''Titanic'', which won 11 Oscars (a record, tied with Ben-Hur and The Return of the King).'),
  ('cine', '¿Qué película tiene la frase "Sayonara, baby"?', '["Predator","Terminator 2","Rambo","Mad Max"]'::jsonb, 1, '"Sayonara, baby" (en doblaje español) es la frase de Schwarzenegger en "Terminator 2: El Juicio Final" (1991). En inglés: "Hasta la vista, baby".', 'medium', 'Which film has the line ''Hasta la vista, baby''?', '["Predator","Terminator 2","Rambo","Mad Max"]'::jsonb, '''Hasta la vista, baby'' is Schwarzenegger''s line in ''Terminator 2: Judgment Day'' (1991).'),
  ('cine', '¿Quién protagoniza la trilogía original de Indiana Jones?', '["Harrison Ford","Sean Connery","Mel Gibson","Tom Selleck"]'::jsonb, 0, 'Harrison Ford interpreta al arqueólogo Indiana Jones en la saga dirigida por Steven Spielberg desde 1981.', 'easy', 'Who stars in the original Indiana Jones trilogy?', '["Harrison Ford","Sean Connery","Mel Gibson","Tom Selleck"]'::jsonb, 'Harrison Ford plays the archaeologist Indiana Jones in the saga directed by Steven Spielberg since 1981.'),
  ('cine', '¿Qué actriz interpretó a Mia Wallace en "Pulp Fiction"?', '["Uma Thurman","Jennifer Aniston","Bridget Fonda","Cameron Diaz"]'::jsonb, 0, 'Uma Thurman interpretó a Mia Wallace en "Pulp Fiction" (1994). Recibió una nominación al Óscar por su papel.', 'medium', 'Which actress played Mia Wallace in ''Pulp Fiction''?', '["Uma Thurman","Jennifer Aniston","Bridget Fonda","Cameron Diaz"]'::jsonb, 'Uma Thurman played Mia Wallace in ''Pulp Fiction'' (1994). She received an Oscar nomination for her role.'),
  ('cine', '¿Qué película ganó el Óscar a Mejor Película en 2020 (rodada en coreano)?', '["Joker","Roma","Parásitos","1917"]'::jsonb, 2, '"Parásitos" de Bong Joon-ho fue la primera película no en inglés en ganar el Óscar a Mejor Película. Ganó 4 Óscars en total.', 'medium', 'Which film won the Oscar for Best Picture in 2020 (filmed in Korean)?', '["Joker","Roma","Parasite","1917"]'::jsonb, '''Parasite'' by Bong Joon-ho was the first non-English-language film to win the Oscar for Best Picture. It won 4 Oscars in total.'),
  ('cine', '¿Quién dirigió "El Resplandor" (1980)?', '["Hitchcock","Kubrick","Polanski","De Palma"]'::jsonb, 1, 'Stanley Kubrick dirigió "El Resplandor", basada en la novela de Stephen King. Jack Nicholson protagoniza.', 'medium', 'Who directed ''The Shining'' (1980)?', '["Hitchcock","Kubrick","Polanski","De Palma"]'::jsonb, 'Stanley Kubrick directed ''The Shining'', based on Stephen King''s novel. Jack Nicholson stars.'),
  ('cine', '¿Qué serie sigue a un profesor de química que fabrica metanfetamina?', '["The Wire","Breaking Bad","Better Call Saul","Ozark"]'::jsonb, 1, '"Breaking Bad" (2008-2013) cuenta la transformación de Walter White, profesor de química, en el narco Heisenberg.', 'easy', 'Which series follows a chemistry teacher who makes methamphetamine?', '["The Wire","Breaking Bad","Better Call Saul","Ozark"]'::jsonb, '''Breaking Bad'' (2008-2013) tells of the transformation of Walter White, a chemistry teacher, into the drug lord Heisenberg.'),
  ('cine', '¿Qué saga incluye personajes como Frodo y Gandalf?', '["Narnia","Harry Potter","El Señor de los Anillos","Juego de Tronos"]'::jsonb, 2, '"El Señor de los Anillos" de J.R.R. Tolkien fue adaptada por Peter Jackson en 2001-2003. Ganó 17 Óscars en total.', 'easy', 'Which saga includes characters like Frodo and Gandalf?', '["Narnia","Harry Potter","The Lord of the Rings","Game of Thrones"]'::jsonb, '''The Lord of the Rings'' by J.R.R. Tolkien was adapted by Peter Jackson in 2001-2003. It won 17 Oscars in total.'),
  ('cine', '¿Qué demuestra el llamado efecto Kuleshov?', '["La influencia del montaje en la interpretación","La persistencia del color","El uso de sonido diegético","La profundidad de campo"]'::jsonb, 0, 'El efecto Kuleshov muestra que el público interpreta un plano de forma distinta según los planos que lo acompañan.', 'hard', 'What does the Kuleshov effect demonstrate?', '["How editing influences interpretation","Colour persistence","The use of diegetic sound","Depth of field"]'::jsonb, 'The Kuleshov effect shows that viewers interpret a shot differently depending on the shots placed around it.'),
  ('cine', '¿Qué actor interpretó al Joker en "El Caballero Oscuro" (2008)?', '["Jack Nicholson","Heath Ledger","Joaquin Phoenix","Cesar Romero"]'::jsonb, 1, 'Heath Ledger interpretó al Joker en "El Caballero Oscuro" de Christopher Nolan. Ganó un Óscar póstumo a Mejor Actor de Reparto.', 'medium', 'Which actor played the Joker in ''The Dark Knight'' (2008)?', '["Jack Nicholson","Heath Ledger","Joaquin Phoenix","Cesar Romero"]'::jsonb, 'Heath Ledger played the Joker in Christopher Nolan''s ''The Dark Knight''. He won a posthumous Oscar for Best Supporting Actor.'),
  ('cine', '¿En qué película Tom Hanks interpreta a un náufrago en una isla?', '["Forrest Gump","Cast Away","The Terminal","Big"]'::jsonb, 1, '"Cast Away" (Náufrago, 2000) dirigida por Robert Zemeckis. Hanks habla con una pelota llamada Wilson.', 'medium', 'In which film does Tom Hanks play a castaway on an island?', '["Forrest Gump","Cast Away","The Terminal","Big"]'::jsonb, '''Cast Away'' (2000) directed by Robert Zemeckis. Hanks talks to a ball named Wilson.'),
  ('cine', '¿Quién dirigió "Vértigo" y "Psicosis"?', '["Hitchcock","Lang","Welles","Wilder"]'::jsonb, 0, 'Alfred Hitchcock, el "maestro del suspense", dirigió "Vértigo" (1958) y "Psicosis" (1960), entre muchos otros clásicos.', 'easy', 'Who directed ''Vertigo'' and ''Psycho''?', '["Hitchcock","Lang","Welles","Wilder"]'::jsonb, 'Alfred Hitchcock, the ''master of suspense'', directed ''Vertigo'' (1958) and ''Psycho'' (1960), among many other classics.'),
  ('cine', '¿Qué serie de HBO se basa en los libros de George R.R. Martin?', '["Vikingos","Juego de Tronos","Roma","Westworld"]'::jsonb, 1, '"Juego de Tronos" (2011-2019) adaptó "Canción de Hielo y Fuego". Es una de las series más vistas de la historia.', 'easy', 'Which HBO series is based on George R.R. Martin''s books?', '["Vikings","Game of Thrones","Rome","Westworld"]'::jsonb, '''Game of Thrones'' (2011-2019) adapted ''A Song of Ice and Fire''. It is one of the most-watched series in history.'),
  ('cine', '¿Qué actor protagoniza la saga "Misión: Imposible"?', '["Brad Pitt","Tom Cruise","Matt Damon","Daniel Craig"]'::jsonb, 1, 'Tom Cruise interpreta a Ethan Hunt desde 1996. Es famoso por hacer sus propias escenas de acción.', 'easy', 'Which actor stars in the ''Mission: Impossible'' saga?', '["Brad Pitt","Tom Cruise","Matt Damon","Daniel Craig"]'::jsonb, 'Tom Cruise has played Ethan Hunt since 1996. He is famous for doing his own action scenes.'),
  ('cine', '¿Qué película de Disney/Pixar trata sobre las emociones?', '["Up","Inside Out","Coco","Soul"]'::jsonb, 1, '"Inside Out" (Del revés, 2015) muestra las emociones (Alegría, Tristeza, Ira, Miedo, Asco) dentro de la mente de una niña.', 'easy', 'Which Disney/Pixar film is about the emotions?', '["Up","Inside Out","Coco","Soul"]'::jsonb, '''Inside Out'' (2015) shows the emotions (Joy, Sadness, Anger, Fear, Disgust) inside the mind of a girl.'),
  ('cine', '¿En qué año se estrenó "Avatar"?', '["2007","2009","2011","2013"]'::jsonb, 1, '"Avatar" de James Cameron se estrenó en diciembre de 2009. Fue la película más taquillera hasta ser superada (y recuperar el récord).', 'medium', 'In what year was ''Avatar'' released?', '["2007","2009","2011","2013"]'::jsonb, 'James Cameron''s ''Avatar'' was released in December 2009. It was the highest-grossing film until it was surpassed (and it later reclaimed the record).'),
  ('cine', '¿Quién es el director de la trilogía "El Caballero Oscuro"?', '["Tim Burton","Christopher Nolan","Zack Snyder","Sam Raimi"]'::jsonb, 1, 'Christopher Nolan dirigió "Batman Begins" (2005), "El Caballero Oscuro" (2008) y "El Caballero Oscuro: La Leyenda Renace" (2012).', 'easy', 'Who is the director of ''The Dark Knight'' trilogy?', '["Tim Burton","Christopher Nolan","Zack Snyder","Sam Raimi"]'::jsonb, 'Christopher Nolan directed ''Batman Begins'' (2005), ''The Dark Knight'' (2008) and ''The Dark Knight Rises'' (2012).'),
  ('cine', '¿Qué actor interpretó a Forrest Gump y Woody (en "Toy Story")?', '["Tom Hanks","Tim Allen","Robin Williams","Jim Carrey"]'::jsonb, 0, 'Tom Hanks puso voz a Woody en "Toy Story" e interpretó a Forrest Gump en 1994.', 'easy', 'Which actor played Forrest Gump and Woody (in ''Toy Story'')?', '["Tom Hanks","Tim Allen","Robin Williams","Jim Carrey"]'::jsonb, 'Tom Hanks voiced Woody in ''Toy Story'' and played Forrest Gump in 1994.'),
  ('cine', '¿Quién compuso la banda sonora de "Star Wars"?', '["Hans Zimmer","John Williams","Ennio Morricone","James Horner"]'::jsonb, 1, 'John Williams compuso la BSO icónica de "Star Wars", "Indiana Jones", "Tiburón" y "E.T." Acumula 54 nominaciones al Óscar.', 'medium', 'Who composed the ''Star Wars'' soundtrack?', '["Hans Zimmer","John Williams","Ennio Morricone","James Horner"]'::jsonb, 'John Williams composed the iconic scores for ''Star Wars'', ''Indiana Jones'', ''Jaws'' and ''E.T.'' He has 54 Oscar nominations.'),
  ('cine', '¿Qué película protagoniza Russell Crowe como gladiador?', '["Troya","Gladiator","Braveheart","300"]'::jsonb, 1, '"Gladiator" (Ridley Scott, 2000) ganó 5 Óscars incluyendo Mejor Película y Mejor Actor para Crowe como Máximo Décimo Meridio.', 'easy', 'Which film stars Russell Crowe as a gladiator?', '["Troy","Gladiator","Braveheart","300"]'::jsonb, '''Gladiator'' (Ridley Scott, 2000) won 5 Oscars including Best Picture and Best Actor for Crowe as Maximus Decimus Meridius.'),
  ('cine', '¿Qué saga de ciencia ficción incluye a Neo y la Matrix?', '["Matrix","Inception","Blade Runner","Tron"]'::jsonb, 0, '"The Matrix" (1999) de las Wachowski. Keanu Reeves interpreta a Neo, el "elegido" para liberar a la humanidad de la simulación.', 'easy', 'Which sci-fi saga includes Neo and the Matrix?', '["The Matrix","Inception","Blade Runner","Tron"]'::jsonb, '''The Matrix'' (1999) by the Wachowskis. Keanu Reeves plays Neo, ''the One'' chosen to free humanity from the simulation.'),
  ('cine', '¿Quién dirigió "La La Land"?', '["Damien Chazelle","David Fincher","Wes Anderson","Greta Gerwig"]'::jsonb, 0, 'Damien Chazelle dirigió "La La Land" (2016), ganadora de 6 Óscars incluyendo Mejor Director (el más joven en obtenerlo: 32 años).', 'medium', 'Who directed ''La La Land''?', '["Damien Chazelle","David Fincher","Wes Anderson","Greta Gerwig"]'::jsonb, 'Damien Chazelle directed ''La La Land'' (2016), winner of 6 Oscars including Best Director (the youngest to win it: 32 years old).'),
  ('cine', '¿Qué actor protagoniza "El Lobo de Wall Street"?', '["Leonardo DiCaprio","Brad Pitt","Christian Bale","Matthew McConaughey"]'::jsonb, 0, 'Leonardo DiCaprio interpreta a Jordan Belfort en "El Lobo de Wall Street" (2013), dirigida por Martin Scorsese.', 'easy', 'Which actor stars in ''The Wolf of Wall Street''?', '["Leonardo DiCaprio","Brad Pitt","Christian Bale","Matthew McConaughey"]'::jsonb, 'Leonardo DiCaprio plays Jordan Belfort in ''The Wolf of Wall Street'' (2013), directed by Martin Scorsese.'),
  ('cine', '¿En qué isla se rueda "Lost"?', '["Maui","Oahu","Hawái","Kauai"]'::jsonb, 1, '"Lost" (2004-2010) se rodó principalmente en Oahu (Hawái). Aunque la isla de la ficción es no localizada.', 'hard', 'On which island is ''Lost'' filmed?', '["Maui","Oahu","Hawaii","Kauai"]'::jsonb, '''Lost'' (2004-2010) was filmed mainly on Oahu (Hawaii). Although the fictional island is unlocated.'),
  ('cine', '¿Qué inventores organizaron una célebre proyección pública de cine en París en 1895?', '["Los hermanos Lumière","Los hermanos Warner","Los hermanos Coen","Los hermanos Marx"]'::jsonb, 0, 'Auguste y Louis Lumière presentaron públicamente su cinematógrafo en el Grand Café de París el 28 de diciembre de 1895.', 'medium', 'Which inventors held a famous public film screening in Paris in 1895?', '["The Lumière brothers","The Warner brothers","The Coen brothers","The Marx Brothers"]'::jsonb, 'Auguste and Louis Lumière publicly presented their Cinématographe at the Grand Café in Paris on 28 December 1895.'),
  ('cine', '¿Qué saga de Marvel terminó con "Endgame"?', '["Saga del infinito","Saga del multiverso","Saga de Asgard","Saga de los X-Men"]'::jsonb, 0, '"Vengadores: Endgame" (2019) cerró la Saga del Infinito (Fases 1-3) del MCU. Es una de las películas más taquilleras de la historia.', 'easy', 'Which Marvel saga ended with ''Endgame''?', '["The Infinity Saga","The Multiverse Saga","The Asgard Saga","The X-Men Saga"]'::jsonb, '''Avengers: Endgame'' (2019) closed the Infinity Saga (Phases 1-3) of the MCU. It is one of the highest-grossing films in history.'),
  ('cine', '¿En qué ciudad transcurre "Casablanca"?', '["Tánger","Casablanca","Argel","El Cairo"]'::jsonb, 1, '"Casablanca" (1942) transcurre en Marruecos durante la Segunda Guerra Mundial. Bogart y Bergman protagonizan.', 'easy', 'In which city does ''Casablanca'' take place?', '["Tangier","Casablanca","Algiers","Cairo"]'::jsonb, '''Casablanca'' (1942) takes place in Morocco during World War II. Bogart and Bergman star.'),
  ('cine', '¿Qué película popularizó la frase "May the Force be with you"?', '["Star Trek","Star Wars","Dune","Stargate"]'::jsonb, 1, '"Que la Fuerza te acompañe" es la frase icónica de "Star Wars" desde 1977. El 4 de mayo (May the 4th) es el día oficial.', 'easy', 'Which film popularized the phrase ''May the Force be with you''?', '["Star Trek","Star Wars","Dune","Stargate"]'::jsonb, '''May the Force be with you'' is the iconic phrase from ''Star Wars'' since 1977. May the 4th is the official day.'),
  ('cine', '¿Quién dirigió "Inception" y "Tenet"?', '["Denis Villeneuve","Christopher Nolan","Ridley Scott","David Fincher"]'::jsonb, 1, 'Christopher Nolan dirigió "Inception" (2010) y "Tenet" (2020), ambas con tramas no lineales y conceptos físicos complejos.', 'medium', 'Who directed ''Inception'' and ''Tenet''?', '["Denis Villeneuve","Christopher Nolan","Ridley Scott","David Fincher"]'::jsonb, 'Christopher Nolan directed ''Inception'' (2010) and ''Tenet'' (2020), both with non-linear plots and complex physics concepts.'),
  ('cine', '¿Qué actriz ganó el Óscar por "La La Land"?', '["Emma Watson","Emma Stone","Jennifer Lawrence","Natalie Portman"]'::jsonb, 1, 'Emma Stone ganó el Óscar a Mejor Actriz por "La La Land" (2016). Ganaría otro por "Pobres criaturas" (2024).', 'medium', 'Which actress won the Oscar for ''La La Land''?', '["Emma Watson","Emma Stone","Jennifer Lawrence","Natalie Portman"]'::jsonb, 'Emma Stone won the Oscar for Best Actress for ''La La Land'' (2016). She would win another for ''Poor Things'' (2024).'),
  ('cine', '¿Qué actor interpreta a James Bond en "Casino Royale" (2006)?', '["Pierce Brosnan","Daniel Craig","Sean Connery","Timothy Dalton"]'::jsonb, 1, 'Daniel Craig fue Bond entre 2006 ("Casino Royale") y 2021 ("Sin tiempo para morir"), reinventando al personaje.', 'easy', 'Which actor plays James Bond in ''Casino Royale'' (2006)?', '["Pierce Brosnan","Daniel Craig","Sean Connery","Timothy Dalton"]'::jsonb, 'Daniel Craig was Bond between 2006 (''Casino Royale'') and 2021 (''No Time to Die''), reinventing the character.'),
  ('cine', '¿Qué película documenta el ascenso de Facebook?', '["La Red Social","Steve Jobs","The Founder","Snowden"]'::jsonb, 0, '"La Red Social" (David Fincher, 2010) dramatiza la fundación de Facebook por Mark Zuckerberg. Guion de Aaron Sorkin.', 'medium', 'Which film documents the rise of Facebook?', '["The Social Network","Steve Jobs","The Founder","Snowden"]'::jsonb, '''The Social Network'' (David Fincher, 2010) dramatizes the founding of Facebook by Mark Zuckerberg. Screenplay by Aaron Sorkin.'),
  ('cine', '¿Qué directores redactaron el manifiesto cinematográfico Dogma 95?', '["Lars von Trier y Thomas Vinterberg","Bergman y Tarkovski","Godard y Truffaut","Fellini y Antonioni"]'::jsonb, 0, 'Lars von Trier y Thomas Vinterberg presentaron Dogma 95 como un conjunto de reglas para reducir artificios cinematográficos.', 'hard', 'Which directors wrote the Dogme 95 filmmaking manifesto?', '["Lars von Trier and Thomas Vinterberg","Bergman and Tarkovsky","Godard and Truffaut","Fellini and Antonioni"]'::jsonb, 'Lars von Trier and Thomas Vinterberg introduced Dogme 95 as a set of rules intended to reduce cinematic artifice.'),
  ('cine', '¿Qué profesional de cine recrea sonidos cotidianos sincronizados con la imagen?', '["Artista de foley","Gaffer","Script supervisor","Colorista"]'::jsonb, 0, 'El artista de foley interpreta y graba pasos, roces y otros efectos en sincronía con las imágenes durante la posproducción.', 'medium', 'Which film professional recreates everyday sounds in sync with the picture?', '["Foley artist","Gaffer","Script supervisor","Colourist"]'::jsonb, 'A Foley artist performs and records footsteps, rustling and other effects in sync with the images during post-production.'),
  ('cine', '¿Qué serie española sigue a un grupo de atracadores con caretas de Dalí?', '["Élite","La Casa de Papel","Vis a Vis","Las Chicas del Cable"]'::jsonb, 1, '"La Casa de Papel" (2017-2021) de Álex Pina se convirtió en un fenómeno internacional en Netflix. El Profesor lidera la banda.', 'easy', 'Which Spanish series follows a group of robbers wearing Dalí masks?', '["Elite","Money Heist","Locked Up","Cable Girls"]'::jsonb, '''Money Heist'' (2017-2021) by Álex Pina became an international phenomenon on Netflix. The Professor leads the gang.'),
  ('cine', '¿Qué película de Spielberg trata sobre un T-Rex que escapa de un parque?', '["E.T.","Jurassic Park","Tiburón","La guerra de los mundos"]'::jsonb, 1, '"Parque Jurásico" (Jurassic Park, 1993) revolucionó los efectos visuales con CGI. Basada en la novela de Michael Crichton.', 'easy', 'Which Spielberg film is about a T-Rex that escapes from a park?', '["E.T.","Jurassic Park","Jaws","War of the Worlds"]'::jsonb, '''Jurassic Park'' (1993) revolutionized visual effects with CGI. Based on Michael Crichton''s novel.'),
  ('cine', '¿Quién protagoniza "Volver" (2006) de Almodóvar?', '["Carmen Maura","Penélope Cruz","Marisa Paredes","Victoria Abril"]'::jsonb, 1, 'Penélope Cruz protagoniza "Volver", por la que fue nominada al Óscar (primera actriz española nominada como Mejor Actriz).', 'medium', 'Who stars in Almodóvar''s ''Volver'' (2006)?', '["Carmen Maura","Penélope Cruz","Marisa Paredes","Victoria Abril"]'::jsonb, 'Penélope Cruz stars in ''Volver'', for which she was nominated for an Oscar (the first Spanish actress nominated for Best Actress).'),
  ('cine', '¿Qué describe el “efecto Rashomon”?', '["Relatos contradictorios sobre un mismo hecho","Una narración en tiempo real","Una película sin diálogos","Un final circular"]'::jsonb, 0, 'El término procede de “Rashomon” de Kurosawa y describe versiones incompatibles de un mismo acontecimiento.', 'medium', 'What does the Rashomon effect describe?', '["Conflicting accounts of the same event","A story told in real time","A film without dialogue","A circular ending"]'::jsonb, 'The term comes from Kurosawa’s Rashomon and describes incompatible accounts of the same event.'),
  ('cine', '¿Quién dirigió la película muda “Nosferatu” de 1922?', '["F. W. Murnau","Fritz Lang","Robert Wiene","G. W. Pabst"]'::jsonb, 0, 'F. W. Murnau dirigió “Nosferatu”, adaptación no autorizada de la novela “Drácula”.', 'hard', 'Who directed the 1922 silent film Nosferatu?', '["F. W. Murnau","Fritz Lang","Robert Wiene","G. W. Pabst"]'::jsonb, 'F. W. Murnau directed Nosferatu, an unauthorized adaptation of the novel Dracula.'),
  ('cine', '¿Qué actriz interpreta a Hermione en "Harry Potter"?', '["Emma Stone","Emma Watson","Keira Knightley","Saoirse Ronan"]'::jsonb, 1, 'Emma Watson interpretó a Hermione Granger en las 8 películas de Harry Potter (2001-2011).', 'easy', 'Which actress plays Hermione in ''Harry Potter''?', '["Emma Stone","Emma Watson","Keira Knightley","Saoirse Ronan"]'::jsonb, 'Emma Watson played Hermione Granger in the 8 Harry Potter films (2001-2011).'),
  ('cine', '¿Qué serie sigue a la familia Roy en torno a una empresa de medios?', '["Billions","Succession","Industry","The Morning Show"]'::jsonb, 1, '"Succession" (HBO, 2018-2023) creada por Jesse Armstrong. Ganó 13 Emmys en su última temporada.', 'medium', 'Which series follows the Roy family around a media company?', '["Billions","Succession","Industry","The Morning Show"]'::jsonb, '''Succession'' (HBO, 2018-2023) created by Jesse Armstrong. It won 13 Emmys in its final season.'),
  ('cine', '¿Qué actor protagonizó "Mejor... imposible" (1997)?', '["Robert De Niro","Jack Nicholson","Al Pacino","Dustin Hoffman"]'::jsonb, 1, 'Jack Nicholson ganó el Óscar a Mejor Actor por "Mejor... imposible" (As Good as It Gets), de James L. Brooks.', 'hard', 'Which actor starred in ''As Good as It Gets'' (1997)?', '["Robert De Niro","Jack Nicholson","Al Pacino","Dustin Hoffman"]'::jsonb, 'Jack Nicholson won the Oscar for Best Actor for ''As Good as It Gets'', by James L. Brooks.'),
  ('cine', '¿Qué película fue la primera en ganar el Óscar a Mejor Película de Animación?', '["Toy Story","Shrek","La Sirenita","El Rey León"]'::jsonb, 1, '"Shrek" (DreamWorks, 2001) ganó el primer Óscar a Mejor Película de Animación, categoría creada en 2002.', 'hard', 'Which film was the first to win the Oscar for Best Animated Feature?', '["Toy Story","Shrek","The Little Mermaid","The Lion King"]'::jsonb, '''Shrek'' (DreamWorks, 2001) won the first Oscar for Best Animated Feature, a category created in 2002.'),
  ('cine', '¿En qué saga aparece el personaje Tony Stark / Iron Man?', '["DC","Marvel","Image","Dark Horse"]'::jsonb, 1, 'Tony Stark / Iron Man pertenece a Marvel. Robert Downey Jr. lo interpretó en el MCU desde 2008 hasta 2019.', 'easy', 'In which saga does the character Tony Stark / Iron Man appear?', '["DC","Marvel","Image","Dark Horse"]'::jsonb, 'Tony Stark / Iron Man belongs to Marvel. Robert Downey Jr. played him in the MCU from 2008 to 2019.'),
  ('musica', '¿Cuántas cuerdas tiene una guitarra clásica estándar?', '["4","5","6","7"]'::jsonb, 2, 'La guitarra clásica española tiene 6 cuerdas afinadas E-A-D-G-B-E. Variantes incluyen guitarras de 7 o 12 cuerdas.', 'easy', 'How many strings does a standard classical guitar have?', '["4","5","6","7"]'::jsonb, 'The Spanish classical guitar has 6 strings tuned E-A-D-G-B-E. Variants include 7- or 12-string guitars.'),
  ('musica', '¿Qué intervalo musical abarca tres tonos enteros?', '["Tritono","Tercera menor","Quinta justa","Octava"]'::jsonb, 0, 'El tritono divide la octava en dos partes iguales y comprende seis semitonos.', 'hard', 'Which musical interval spans three whole tones?', '["Tritone","Minor third","Perfect fifth","Octave"]'::jsonb, 'The tritone divides the octave into two equal parts and spans six semitones.'),
  ('musica', '¿De qué ciudad son originarios Los Beatles?', '["Londres","Manchester","Liverpool","Birmingham"]'::jsonb, 2, 'Los Beatles se formaron en Liverpool en 1960. John Lennon, Paul McCartney, George Harrison y Ringo Starr.', 'easy', 'Which city are The Beatles from?', '["London","Manchester","Liverpool","Birmingham"]'::jsonb, 'The Beatles formed in Liverpool in 1960. John Lennon, Paul McCartney, George Harrison and Ringo Starr.'),
  ('musica', '¿Quién es conocido como el "Rey del Pop"?', '["Elvis Presley","Michael Jackson","Prince","Madonna"]'::jsonb, 1, 'Michael Jackson (1958-2009) recibió ese título. Su álbum "Thriller" (1982) sigue siendo el más vendido de la historia (~70 M).', 'easy', 'Who is known as the ''King of Pop''?', '["Elvis Presley","Michael Jackson","Prince","Madonna"]'::jsonb, 'Michael Jackson (1958-2009) received that title. His album ''Thriller'' (1982) is still the best-selling in history (~70 M).'),
  ('musica', '¿Cuál es el instrumento típico de Andrés Segovia?', '["Piano","Violín","Guitarra","Flauta"]'::jsonb, 2, 'Andrés Segovia (1893-1987) elevó la guitarra clásica al estatus de instrumento solista de concierto.', 'medium', 'What is the typical instrument of Andrés Segovia?', '["Piano","Violin","Guitar","Flute"]'::jsonb, 'Andrés Segovia (1893-1987) elevated the classical guitar to the status of a solo concert instrument.'),
  ('musica', '¿Qué cantante puertorriqueño popularizó "Despacito" en 2017?', '["Daddy Yankee","Luis Fonsi","Ozuna","Don Omar"]'::jsonb, 1, 'Luis Fonsi lanzó "Despacito" (con Daddy Yankee) en 2017. Su remix con Justin Bieber rompió récords en YouTube.', 'easy', 'Which Puerto Rican singer popularized ''Despacito'' in 2017?', '["Daddy Yankee","Luis Fonsi","Ozuna","Don Omar"]'::jsonb, 'Luis Fonsi released ''Despacito'' (with Daddy Yankee) in 2017. Its remix with Justin Bieber broke records on YouTube.'),
  ('musica', '¿En qué región nació el tango moderno?', '["Río de la Plata","Andes centrales","Caribe insular","Patagonia"]'::jsonb, 0, 'El tango se desarrolló a finales del siglo XIX en ciudades portuarias del Río de la Plata, especialmente Buenos Aires y Montevideo.', 'medium', 'In which region did modern tango originate?', '["Río de la Plata","Central Andes","Caribbean islands","Patagonia"]'::jsonb, 'Tango developed in the late nineteenth century in Río de la Plata port cities, especially Buenos Aires and Montevideo.'),
  ('musica', '¿De qué tradición musical procede el conjunto llamado gamelán?', '["Indonesia","Irlanda","Etiopía","Canadá"]'::jsonb, 0, 'El gamelán es una agrupación tradicional de Indonesia, especialmente de Java y Bali, basada en metalófonos, gongs y tambores.', 'medium', 'Which musical tradition does the ensemble called gamelan come from?', '["Indonesia","Ireland","Ethiopia","Canada"]'::jsonb, 'Gamelan is a traditional Indonesian ensemble, especially from Java and Bali, built around metallophones, gongs and drums.'),
  ('musica', '¿Cuántas notas musicales tiene la escala diatónica?', '["5","7","8","12"]'::jsonb, 1, 'La escala diatónica tiene 7 notas: do, re, mi, fa, sol, la, si. Repitiendo, se vuelve al do para la octava.', 'easy', 'How many notes does the diatonic scale have?', '["5","7","8","12"]'::jsonb, 'The diatonic scale has 7 notes: do, re, mi, fa, sol, la, si. Repeating, it returns to do for the octave.'),
  ('musica', '¿Quién fue conocido como el "Rey del Rock and Roll"?', '["Chuck Berry","Elvis Presley","Little Richard","Bill Haley"]'::jsonb, 1, 'Elvis Presley (1935-1977) popularizó el rock and roll en los años 50. Vendió más de 500 millones de discos.', 'easy', 'Who was known as the ''King of Rock and Roll''?', '["Chuck Berry","Elvis Presley","Little Richard","Bill Haley"]'::jsonb, 'Elvis Presley (1935-1977) popularized rock and roll in the 1950s. He sold more than 500 million records.'),
  ('musica', '¿Qué banda escribió "Bohemian Rhapsody"?', '["Led Zeppelin","Queen","The Who","Pink Floyd"]'::jsonb, 1, '"Bohemian Rhapsody" de Queen (1975), compuesta por Freddie Mercury. Dura 5:55 y mezcla balada, ópera y rock.', 'easy', 'Which band wrote ''Bohemian Rhapsody''?', '["Led Zeppelin","Queen","The Who","Pink Floyd"]'::jsonb, '''Bohemian Rhapsody'' by Queen (1975), composed by Freddie Mercury. It lasts 5:55 and mixes ballad, opera and rock.'),
  ('musica', '¿En qué país nació Plácido Domingo?', '["México","España","Argentina","Italia"]'::jsonb, 1, 'Plácido Domingo nació en Madrid en 1941 y emigró con su familia a México de niño. Es uno de los Tres Tenores.', 'medium', 'In which country was Plácido Domingo born?', '["Mexico","Spain","Argentina","Italy"]'::jsonb, 'Plácido Domingo was born in Madrid in 1941 and emigrated with his family to Mexico as a child. He is one of the Three Tenors.'),
  ('musica', '¿Qué relación organiza el círculo de quintas?', '["Las tonalidades según sus alteraciones","Los tempos de una sinfonía","Las familias de instrumentos","Los tipos de voz"]'::jsonb, 0, 'El círculo de quintas dispone las tonalidades por intervalos de quinta y permite visualizar sus sostenidos, bemoles y relaciones armónicas.', 'hard', 'What relationship does the circle of fifths organize?', '["Keys according to their accidentals","The tempos of a symphony","Instrument families","Voice types"]'::jsonb, 'The circle of fifths arranges keys by intervals of a fifth and shows their sharps, flats and harmonic relationships.'),
  ('musica', '¿Qué cantante británica murió en 2011 con 27 años?', '["Adele","Amy Winehouse","Lana del Rey","Florence Welch"]'::jsonb, 1, 'Amy Winehouse (1983-2011) murió a los 27 años por intoxicación alcohólica. Su álbum "Back to Black" ganó 5 Grammys.', 'medium', 'Which British singer died in 2011 at age 27?', '["Adele","Amy Winehouse","Lana del Rey","Florence Welch"]'::jsonb, 'Amy Winehouse (1983-2011) died at age 27 of alcohol poisoning. Her album ''Back to Black'' won 5 Grammys.'),
  ('musica', '¿Quién compuso la ópera "El barbero de Sevilla"?', '["Mozart","Verdi","Rossini","Wagner"]'::jsonb, 2, 'Gioachino Rossini estrenó "El barbero de Sevilla" en 1816. Es una de las óperas cómicas más representadas.', 'hard', 'Who composed the opera ''The Barber of Seville''?', '["Mozart","Verdi","Rossini","Wagner"]'::jsonb, 'Gioachino Rossini premiered ''The Barber of Seville'' in 1816. It is one of the most performed comic operas.'),
  ('musica', '¿Qué danza polaca en compás ternario inspiró numerosas piezas de Chopin?', '["Mazurca","Sarabanda","Gavota","Tarantela"]'::jsonb, 0, 'Chopin compuso decenas de mazurcas, estilizando una familia de danzas populares polacas en compás ternario.', 'medium', 'Which Polish dance in triple metre inspired numerous pieces by Chopin?', '["Mazurka","Sarabande","Gavotte","Tarantella"]'::jsonb, 'Chopin composed dozens of mazurkas, stylizing a family of Polish folk dances in triple metre.'),
  ('musica', '¿Qué grupo escribió "Stairway to Heaven"?', '["Pink Floyd","Led Zeppelin","Black Sabbath","Deep Purple"]'::jsonb, 1, 'Led Zeppelin grabó "Stairway to Heaven" en su álbum sin título de 1971 (Led Zeppelin IV). Es una de las canciones más icónicas del rock.', 'medium', 'Which band wrote ''Stairway to Heaven''?', '["Pink Floyd","Led Zeppelin","Black Sabbath","Deep Purple"]'::jsonb, 'Led Zeppelin recorded ''Stairway to Heaven'' on their untitled 1971 album (Led Zeppelin IV). It is one of the most iconic rock songs.'),
  ('musica', '¿Quién compuso la "Marcha Nupcial" (Bridal Chorus)?', '["Mendelssohn","Wagner","Bach","Strauss"]'::jsonb, 1, 'La famosa "Marcha Nupcial" ("Here Comes the Bride") es de Richard Wagner, de su ópera "Lohengrin" (1850).', 'hard', 'Who composed the ''Bridal Chorus'' (Wedding March)?', '["Mendelssohn","Wagner","Bach","Strauss"]'::jsonb, 'The famous ''Bridal Chorus'' (''Here Comes the Bride'') is by Richard Wagner, from his opera ''Lohengrin'' (1850).'),
  ('musica', '¿Quién compuso la canción mexicana “Cielito lindo”?', '["Quirino Mendoza y Cortés","Agustín Lara","José Alfredo Jiménez","Manuel M. Ponce"]'::jsonb, 0, 'Quirino Mendoza y Cortés compuso “Cielito lindo” en 1882; la canción se convirtió en un emblema musical mexicano.', 'hard', 'Who composed the Mexican song Cielito Lindo?', '["Quirino Mendoza y Cortés","Agustín Lara","José Alfredo Jiménez","Manuel M. Ponce"]'::jsonb, 'Quirino Mendoza y Cortés composed Cielito Lindo in 1882; the song became a Mexican musical emblem.'),
  ('musica', '¿Qué cantante popularizó "Like a Virgin"?', '["Madonna","Cyndi Lauper","Whitney Houston","Tina Turner"]'::jsonb, 0, 'Madonna lanzó "Like a Virgin" en 1984. El álbum vendió más de 21 millones de copias y consolidó su carrera.', 'easy', 'Which singer popularized ''Like a Virgin''?', '["Madonna","Cyndi Lauper","Whitney Houston","Tina Turner"]'::jsonb, 'Madonna released ''Like a Virgin'' in 1984. The album sold more than 21 million copies and consolidated her career.'),
  ('musica', '¿En qué siglo vivió Johann Sebastian Bach?', '["XVI","XVII","XVII-XVIII","XVIII-XIX"]'::jsonb, 2, 'J.S. Bach (1685-1750), del Barroco tardío. Sus obras (BWV) suman más de 1.100 piezas.', 'medium', 'In which century did Johann Sebastian Bach live?', '["16th","17th","17th-18th","18th-19th"]'::jsonb, 'J.S. Bach (1685-1750), of the late Baroque. His works (BWV) add up to more than 1,100 pieces.'),
  ('musica', '¿Qué instrumento toca Yo-Yo Ma?', '["Violín","Viola","Violonchelo","Contrabajo"]'::jsonb, 2, 'Yo-Yo Ma es un violonchelista estadounidense de origen chino. Ha ganado 19 Grammys y es uno de los músicos más influyentes vivos.', 'medium', 'Which instrument does Yo-Yo Ma play?', '["Violin","Viola","Cello","Double bass"]'::jsonb, 'Yo-Yo Ma is an American cellist of Chinese origin. He has won 19 Grammys and is one of the most influential living musicians.'),
  ('musica', '¿Cuántos miembros componen Coldplay?', '["3","4","5","6"]'::jsonb, 1, 'Coldplay tiene 4 miembros: Chris Martin (voz), Jonny Buckland (guitarra), Guy Berryman (bajo) y Will Champion (batería).', 'medium', 'How many members make up Coldplay?', '["3","4","5","6"]'::jsonb, 'Coldplay has 4 members: Chris Martin (vocals), Jonny Buckland (guitar), Guy Berryman (bass) and Will Champion (drums).'),
  ('musica', '¿Qué instrumento indio de cuerda tocaba Ravi Shankar?', '["Sitar","Sarod","Tabla","Bansuri"]'::jsonb, 0, 'Ravi Shankar fue un virtuoso del sitar y contribuyó decisivamente a divulgar la música clásica india en Occidente.', 'medium', 'Which Indian string instrument did Ravi Shankar play?', '["Sitar","Sarod","Tabla","Bansuri"]'::jsonb, 'Ravi Shankar was a sitar virtuoso who played a major role in introducing Indian classical music to Western audiences.'),
  ('musica', '¿En qué país surgió el flamenco?', '["Marruecos","Portugal","España","Italia"]'::jsonb, 2, 'El flamenco surgió en Andalucía (España) en el siglo XVIII, con influencias gitanas, andaluzas y árabes. Es Patrimonio de la UNESCO.', 'easy', 'In which country did flamenco originate?', '["Morocco","Portugal","Spain","Italy"]'::jsonb, 'Flamenco originated in Andalusia (Spain) in the 18th century, with Roma, Andalusian and Arab influences. It is UNESCO heritage.'),
  ('musica', '¿Qué cantante española ganó Eurovisión 1968?', '["Karina","Massiel","Salomé","Mocedades"]'::jsonb, 1, 'Massiel ganó Eurovisión 1968 con "La, la, la", tras la negativa de Joan Manuel Serrat a cantarla en español.', 'hard', 'Which Spanish singer won Eurovision 1968?', '["Karina","Massiel","Salomé","Mocedades"]'::jsonb, 'Massiel won Eurovision 1968 with ''La, la, la'', after Joan Manuel Serrat refused to sing it in Spanish.'),
  ('musica', '¿Qué músico es conocido como "The Boss"?', '["Bob Dylan","Bruce Springsteen","Neil Young","Tom Petty"]'::jsonb, 1, 'Bruce Springsteen lleva el apodo de "The Boss" desde los 70. Su álbum "Born in the USA" (1984) vendió 30 M de copias.', 'medium', 'Which musician is known as ''The Boss''?', '["Bob Dylan","Bruce Springsteen","Neil Young","Tom Petty"]'::jsonb, 'Bruce Springsteen has had the nickname ''The Boss'' since the 70s. His album ''Born in the USA'' (1984) sold 30 M copies.'),
  ('musica', '¿Qué se mide en hercios (Hz) en música?', '["Volumen","Frecuencia","Duración","Timbre"]'::jsonb, 1, 'La frecuencia se mide en Hz (ciclos por segundo). El La estándar es 440 Hz. El humano oye entre ~20 Hz y ~20.000 Hz.', 'medium', 'What is measured in hertz (Hz) in music?', '["Volume","Frequency","Duration","Timbre"]'::jsonb, 'Frequency is measured in Hz (cycles per second). Standard A is 440 Hz. Humans hear between ~20 Hz and ~20,000 Hz.'),
  ('musica', '¿Qué grupo grabó "Dark Side of the Moon"?', '["Genesis","Pink Floyd","Rush","Yes"]'::jsonb, 1, '"The Dark Side of the Moon" de Pink Floyd (1973) estuvo 950 semanas en el Billboard 200 y vendió ~45 M de copias.', 'medium', 'Which band recorded ''Dark Side of the Moon''?', '["Genesis","Pink Floyd","Rush","Yes"]'::jsonb, '''The Dark Side of the Moon'' by Pink Floyd (1973) spent 950 weeks on the Billboard 200 and sold ~45 M copies.'),
  ('musica', '¿Quién compuso "El lago de los cisnes"?', '["Stravinsky","Prokofiev","Tchaikovsky","Rachmaninoff"]'::jsonb, 2, 'Piotr Ilich Tchaikovsky estrenó "El lago de los cisnes" en 1877. Es uno de los ballets más representados.', 'medium', 'Who composed ''Swan Lake''?', '["Stravinsky","Prokofiev","Tchaikovsky","Rachmaninoff"]'::jsonb, 'Pyotr Ilyich Tchaikovsky premiered ''Swan Lake'' in 1877. It is one of the most performed ballets.'),
  ('musica', '¿Cuántos miembros tenían los Beatles?', '["3","4","5","6"]'::jsonb, 1, 'Los Beatles fueron 4: John Lennon, Paul McCartney, George Harrison y Ringo Starr (sustituyendo a Pete Best en 1962).', 'easy', 'How many members did the Beatles have?', '["3","4","5","6"]'::jsonb, 'The Beatles were 4: John Lennon, Paul McCartney, George Harrison and Ringo Starr (replacing Pete Best in 1962).'),
  ('musica', '¿Qué cantante de blues es apodado "King of the Blues"?', '["Muddy Waters","B.B. King","John Lee Hooker","Howlin'' Wolf"]'::jsonb, 1, 'B.B. King (1925-2015), guitarrista de blues, llamó "Lucille" a su guitarra Gibson. Influyó en generaciones de músicos.', 'hard', 'Which blues singer is nicknamed ''King of the Blues''?', '["Muddy Waters","B.B. King","John Lee Hooker","Howlin'' Wolf"]'::jsonb, 'B.B. King (1925-2015), a blues guitarist, named his Gibson guitar ''Lucille''. He influenced generations of musicians.'),
  ('musica', '¿Qué tipo de instrumento es la marimba?', '["Cuerda","Viento","Percusión","Electrónico"]'::jsonb, 2, 'La marimba es un idiófono de percusión: barras de madera afinadas que se golpean con baquetas. Es originaria de Centroamérica/África.', 'medium', 'What type of instrument is the marimba?', '["String","Wind","Percussion","Electronic"]'::jsonb, 'The marimba is a percussion idiophone: tuned wooden bars struck with mallets. It originates in Central America/Africa.'),
  ('musica', '¿Qué compositor está especialmente asociado al uso operístico del leitmotiv?', '["Giacomo Puccini","Richard Wagner","Gioachino Rossini","Gaetano Donizetti"]'::jsonb, 1, 'Richard Wagner utilizó motivos musicales recurrentes para representar personajes, objetos e ideas en sus dramas musicales.', 'hard', 'Which composer is especially associated with the operatic use of the leitmotif?', '["Giacomo Puccini","Richard Wagner","Gioachino Rossini","Gaetano Donizetti"]'::jsonb, 'Richard Wagner used recurring musical motifs to represent characters, objects and ideas in his music dramas.'),
  ('musica', '¿Qué cantautor catalán compuso "Mediterráneo" (1971)?', '["Lluís Llach","Joan Manuel Serrat","Raimon","Pau Casals"]'::jsonb, 1, 'Joan Manuel Serrat lanzó "Mediterráneo" en 1971. Es considerada una de las mejores canciones en español de todos los tiempos.', 'hard', 'Which Catalan singer-songwriter composed ''Mediterráneo'' (1971)?', '["Lluís Llach","Joan Manuel Serrat","Raimon","Pau Casals"]'::jsonb, 'Joan Manuel Serrat released ''Mediterráneo'' in 1971. It is considered one of the best Spanish-language songs of all time.'),
  ('musica', '¿Qué grupo lanzó "Hotel California" en 1976?', '["Eagles","Fleetwood Mac","Doobie Brothers","Steely Dan"]'::jsonb, 0, '"Hotel California" de los Eagles ganó el Grammy a Grabación del Año en 1978 y es uno de los himnos del rock clásico.', 'medium', 'Which band released ''Hotel California'' in 1976?', '["Eagles","Fleetwood Mac","Doobie Brothers","Steely Dan"]'::jsonb, '''Hotel California'' by the Eagles won the Grammy for Record of the Year in 1978 and is one of the anthems of classic rock.'),
  ('musica', '¿Qué orquesta dirigió Herbert von Karajan durante décadas?', '["Viena","Berlín","Londres","Nueva York"]'::jsonb, 1, 'Karajan dirigió la Filarmónica de Berlín entre 1955 y 1989. Es uno de los directores más vendidos de la historia.', 'hard', 'Which orchestra did Herbert von Karajan conduct for decades?', '["Vienna","Berlin","London","New York"]'::jsonb, 'Karajan conducted the Berlin Philharmonic between 1955 and 1989. He is one of the best-selling conductors in history.'),
  ('musica', '¿Cuál es la nota más aguda en el pentagrama de clave de sol?', '["Do","Mi","La","Depende"]'::jsonb, 3, 'En clave de sol, las notas suben indefinidamente con líneas adicionales encima del pentagrama. La nota más aguda depende del rango.', 'hard', 'Which is the highest note on the treble-clef staff?', '["Do","Mi","La","It depends"]'::jsonb, 'In the treble clef, notes go up indefinitely with ledger lines above the staff. The highest note depends on the range.'),
  ('musica', '¿Qué cantante británica lanzó "Rolling in the Deep" en 2010?', '["Adele","Amy Winehouse","Florence","Dua Lipa"]'::jsonb, 0, 'Adele lanzó "Rolling in the Deep" en 2010, primer single de su álbum "21", uno de los más vendidos del siglo XXI.', 'easy', 'Which British singer released ''Rolling in the Deep'' in 2010?', '["Adele","Amy Winehouse","Florence","Dua Lipa"]'::jsonb, 'Adele released ''Rolling in the Deep'' in 2010, the first single from her album ''21'', one of the best-selling of the 21st century.'),
  ('musica', '¿Quién popularizó la canción "My Way"?', '["Frank Sinatra","Elvis Presley","Tony Bennett","Bing Crosby"]'::jsonb, 0, '"My Way" se asocia con Frank Sinatra (1969), aunque la letra es de Paul Anka, adaptada de "Comme d''habitude" de Claude François.', 'medium', 'Who popularized the song ''My Way''?', '["Frank Sinatra","Elvis Presley","Tony Bennett","Bing Crosby"]'::jsonb, '''My Way'' is associated with Frank Sinatra (1969), although the lyrics are by Paul Anka, adapted from ''Comme d''habitude'' by Claude François.'),
  ('musica', '¿Qué técnica vocal alterna rápidamente entre el registro de pecho y el de cabeza?', '["Yodel","Scat","Beatboxing","Recitativo"]'::jsonb, 0, 'El yodel se caracteriza por cambios rápidos de registro y es conocido por su presencia en tradiciones alpinas, entre otras.', 'hard', 'Which vocal technique rapidly alternates between chest and head registers?', '["Yodeling","Scat singing","Beatboxing","Recitative"]'::jsonb, 'Yodeling features rapid register changes and is well known in Alpine traditions, among others.'),
  ('musica', '¿Cuántas líneas tiene un pentagrama?', '["3","4","5","6"]'::jsonb, 2, 'Un pentagrama tiene 5 líneas y 4 espacios donde se colocan las notas. Es el sistema occidental estándar desde el siglo XVII.', 'easy', 'How many lines does a staff have?', '["3","4","5","6"]'::jsonb, 'A staff has 5 lines and 4 spaces where the notes are placed. It is the standard Western system since the 17th century.'),
  ('musica', '¿Qué cantante mexicana popularizó la canción "La Llorona"?', '["Lola Beltrán","Chavela Vargas","Lila Downs","Es popular"]'::jsonb, 1, 'Chavela Vargas (1919-2012) popularizó "La Llorona" en su versión más conocida, aunque la canción es popular mexicana del siglo XIX.', 'medium', 'Which Mexican singer popularized the song ''La Llorona''?', '["Lola Beltrán","Chavela Vargas","Lila Downs","It''s a folk song"]'::jsonb, 'Chavela Vargas (1919-2012) popularized ''La Llorona'' in its best-known version, although the song is a 19th-century Mexican folk song.'),
  ('musica', '¿En qué año murió Mozart?', '["1791","1801","1815","1827"]'::jsonb, 0, 'Wolfgang Amadeus Mozart murió el 5 de diciembre de 1791 a los 35 años, sin completar su Réquiem.', 'medium', 'In what year did Mozart die?', '["1791","1801","1815","1827"]'::jsonb, 'Wolfgang Amadeus Mozart died on 5 December 1791 at age 35, without completing his Requiem.'),
  ('musica', '¿Qué músico francés inspiró el impresionismo musical?', '["Ravel","Debussy","Bizet","Saint-Saëns"]'::jsonb, 1, 'Claude Debussy (1862-1918) es el principal exponente del impresionismo musical, con obras como "Claro de luna" y "La mer".', 'hard', 'Which French musician inspired musical impressionism?', '["Ravel","Debussy","Bizet","Saint-Saëns"]'::jsonb, 'Claude Debussy (1862-1918) is the main exponent of musical impressionism, with works like ''Clair de Lune'' and ''La mer''.'),
  ('musica', '¿Qué cantante puertorriqueño es apodado "El Conejo Malo"?', '["Daddy Yankee","Bad Bunny","Ozuna","Anuel AA"]'::jsonb, 1, 'Bad Bunny (Benito Antonio Martínez Ocasio) es el reguetonero/trapero más escuchado del mundo en Spotify en varios años recientes.', 'easy', 'Which Puerto Rican singer is nicknamed ''El Conejo Malo'' (The Bad Bunny)?', '["Daddy Yankee","Bad Bunny","Ozuna","Anuel AA"]'::jsonb, 'Bad Bunny (Benito Antonio Martínez Ocasio) is the most-streamed reggaeton/trap artist in the world on Spotify in several recent years.'),
  ('musica', '¿Qué compositor popularizó el piano preparado?', '["John Cage","Philip Glass","Aaron Copland","Leonard Bernstein"]'::jsonb, 0, 'John Cage transformó el timbre del piano colocando objetos entre sus cuerdas, técnica central en obras como “Sonatas and Interludes”.', 'hard', 'Which composer popularized the prepared piano?', '["John Cage","Philip Glass","Aaron Copland","Leonard Bernstein"]'::jsonb, 'John Cage transformed the piano’s timbre by placing objects between its strings, a technique central to works such as Sonatas and Interludes.'),
  ('musica', '¿Qué grupo grabó "Sweet Child O'' Mine"?', '["Aerosmith","Guns N'' Roses","AC/DC","Bon Jovi"]'::jsonb, 1, '"Sweet Child O''Mine" de Guns N'' Roses, en su álbum debut "Appetite for Destruction" (1987). El riff de Slash es de los más famosos.', 'medium', 'Which band recorded ''Sweet Child O'' Mine''?', '["Aerosmith","Guns N'' Roses","AC/DC","Bon Jovi"]'::jsonb, '''Sweet Child O'' Mine'' by Guns N'' Roses, on their debut album ''Appetite for Destruction'' (1987). Slash''s riff is one of the most famous.'),
  ('musica', '¿Cuántas óperas compuso Mozart (aproximadamente)?', '["12","17","22","30"]'::jsonb, 2, 'Mozart compuso unas 22 óperas, incluyendo "Las bodas de Fígaro" (1786), "Don Giovanni" (1787) y "La flauta mágica" (1791).', 'hard', 'How many operas did Mozart compose (approximately)?', '["12","17","22","30"]'::jsonb, 'Mozart composed about 22 operas, including ''The Marriage of Figaro'' (1786), ''Don Giovanni'' (1787) and ''The Magic Flute'' (1791).'),
  ('literatura', '¿Qué novela española anónima está narrada por un pregonero que sirvió a varios amos?', '["La Celestina","Lazarillo de Tormes","El Buscón","Amadís de Gaula"]'::jsonb, 1, '“Lazarillo de Tormes”, publicada en 1554, relata en primera persona la vida de Lázaro y es una obra fundacional de la novela picaresca.', 'medium', 'Which anonymous Spanish novel is narrated by a town crier who served several masters?', '["La Celestina","Lazarillo de Tormes","El Buscón","Amadís de Gaula"]'::jsonb, 'Lazarillo de Tormes, published in 1554, tells Lázaro’s life in the first person and is a foundational picaresque novel.'),
